/* ───────── monthly learning loop (calibration from the user's own outcomes) ───────── */

/** Stamped on every decision snapshot, so the monthly report knows which engine produced each estimate. */
const ENGINE_VERSION = '1.3.0'

/**
 * The 16 time windows pooled into 5 groups: with a handful of offers a month a single window never collects enough
 * outcomes, a group does. Holidays fall into the Sunday windows, so into the same groups.
 */
const LEARNING_TIME_GROUPS = [
  { id: 'prime_evening', label: 'Sere migliori (dom e lun–gio 21–23)', windows: ['sunday_night', 'weeknight_late', 'weeknight_early', 'weeknight_end'] },
  { id: 'weekend', label: 'Weekend (ven–sab sera, sab–dom di giorno)', windows: ['friday_night', 'saturday_night', 'sunday_afternoon', 'sunday_morning', 'saturday_morning'] },
  { id: 'evening_other', label: 'Ora di cena e fasce neutre', windows: ['after_dinner', 'neutral'] },
  { id: 'daytime', label: 'Giorno lavorativo (7–18)', windows: ['commute', 'work_morning', 'pre_lunch', 'lunch', 'work_afternoon'] },
  { id: 'night', label: 'Notte (0–7)', windows: ['night'] },
]

/**
 * Discount correction as a piecewise-linear curve through three knots (flat outside 10–30%): a step per risk band
 * would make the corrected acceptance jump UP when an offer crosses 15% or 30%, which the price search would exploit.
 */
const LEARNING_DISCOUNT_KNOTS = [
  { id: 'd10', pct: 10, label: 'Sconto intorno al 10%' },
  { id: 'd20', pct: 20, label: 'Sconto intorno al 20%' },
  { id: 'd30', pct: 30, label: 'Sconto dal 30% in su' },
]

/**
 * Parameters of the monthly learning loop (src/core/learning.js). All H (heuristic) unless noted, tuned for a buyer
 * with fewer than 15 offers a month: every learned value starts at the engine default and moves slowly. Logit units
 * unless noted. Sources for the statistical choices: priors and Laplace (Gelman 2008), recalibration before revision
 * at small n (Steyerberg 2004, Vergouwe 2017), prequential rollback (Dawid 1984, Kass & Raftery 1995), conservative
 * batched exploration (Wu 2016, Perchet 2016), counter priors from eBay field data (Backus 2020, Cotet 2025).
 */
const LEARNING = {
  HALF_LIFE_MONTHS: 6,
  PRIOR_SD: { intercept: 0.5, slope: 0.25, time: 0.35, disc: 0.35, counter: 0.5 },
  /** Weighted outcomes a parameter needs before it may move at all. */
  MIN_EFFECTIVE: { intercept: 8, slope: 40, time: 6, disc: 6, counter: 6, discount: 10, share: 8, latency: 8 },
  /** Largest change applied in one month (latency: multiplicative factor). */
  MAX_STEP: { intercept: 0.3, slope: 0.15, time: 0.2, disc: 0.2, counter: 0.3, discountPct: 1, share: 0.1, latency: 1.5 },
  BOUNDS: { intercept: [-1, 1], slope: [0.7, 1.3], time: [-0.6, 0.6], disc: [-0.6, 0.6], counter: [-1, 1], discountPct: [10, 30], share: [0.7, 1.3], latency: [0.5, 12] },
  /** No move while the current value is within this many posterior sd of the target (noise). */
  EVIDENCE_GATE_SD: 0.5,
  /** The slope and the group offsets join only when leave-one-out says they predict better (nats, and ≥ 1 se). */
  LADDER_MIN_ELPD_GAIN: 1,
  /** Corrected acceptance must keep falling with the discount: engine slope ≥ 0,088 logit per point, 80% margin. */
  DISC_MIN_ENGINE_SLOPE: 0.088,
  DISC_MONOTONE_MARGIN: 0.8,
  /** Changes smaller than this are not worth a new profile (logit units, or points for the discount). */
  MIN_CHANGE: 0.02,
  MIN_CHANGE_DISCOUNT_PCT: 1,
  DEFAULT_DISCOUNT_PCT: 20,
  /**
   * The slope scales the engine's logit around this value (a typical offer's logit), so a pure level shift lands in
   * the intercept and the two are nearly uncorrelated (a raw-logit slope absorbed part of every shift).
   */
  SLOPE_CENTER: 1,
  /** Prequential log Bayes factor of the active profile against its parent below which the parent comes back. */
  ROLLBACK_LOG_BF: -2,
  FREEZE_MONTHS: 1,
  /** An offer sent with no outcome after this many days counts as "no reply"; younger offers wait for the next fit. */
  NO_REPLY_AFTER_DAYS: 7,
  /** A counter of ours with no outcome after this many days counts as not accepted. */
  COUNTER_NO_REPLY_AFTER_DAYS: 4,
  /** Exploration: share of first offers that get a small, flagged variation (user choice: about 1 in 5). */
  EXPLORE_SHARE: 0.2,
  EXPLORE_TIME_MINUTES: 60,
  EXPLORE_DISCOUNT_PTS: 2,
  /** A variation is unsafe when it costs more than this in acceptance (probability points)… */
  EXPLORE_MAX_COST: 0.06,
  /** …or in expected saving (share of list price). */
  EXPLORE_MAX_SAVING_COST: 0.01,
  /** Monthly budget: total acceptance given up by variations ≤ this share of the month's total base acceptance. */
  EXPLORE_BUDGET_SHARE: 0.03,
  EXPLORE_MIN_LIST_PRICE: 10,
  /** Reliability table: equal-mass bins, between 2 and this many. */
  RELIABILITY_MAX_BINS: 5,
  /** Months of reports caught up at once when the app was not opened for a while. */
  MAX_CATCH_UP_MONTHS: 6,
  /**
   * Starting discount: iso-acceptance. The learned default is the deepest discount whose corrected acceptance, averaged
   * over the user's own items, is still at least what the plain engine gives at −20%: as far as these sellers allow,
   * at the same chance of success. The expected-saving curve below is reported, not used (its optimum sits on the
   * aggressive-offer knee, so it would not respond smoothly to the data).
   * Expected saving (share of list price): ES(d) = p(d)·d + (1 − p(d))·[q(d)·ρ·d − (1 − q(d))·LOSS].
   * q = chance a failed first offer still ends in a deal, ρ = saving of those deals relative to the first discount,
   * LOSS = cost of losing the item (buying elsewhere at list price + 5%, as COUNTER.LOSS_PREMIUM). Priors with weight.
   * Aggressive openers (27–33%) halve q: an irritated seller rarely keeps negotiating (blockRiskAt's ramp).
   */
  CLOSE_AFTER_FAIL_PRIOR: 0.4,
  CONTINUATION_RATIO_PRIOR: 0.5,
  CONTINUATION_PRIOR_WEIGHT: 4,
  LOSS_COST_SHARE: 0.05,
  AGGRESSIVE_RAMP_PCT: [27, 33],
  /** Failure reasons: engine split of "read but not accepted" (Backus 2020 replies), smoothed with the user's mix. */
  REASON_PRIOR_SPLIT: { countered: 0.45, declined: 0.35, no_reply: 0.2 },
  REASON_PRIOR_WEIGHT: 6,
  /** Chance a negotiation still closes after each kind of failed first offer (prior means, weight in outcomes). */
  CLOSE_AFTER_REASON_PRIOR: { countered: 0.6, declined: 0.1, no_reply: 0.1, sold_other: 0 },
  CLOSE_AFTER_REASON_WEIGHT: 4,
  /** Seller concession share in his first counter (Backus 2020 Table 4: 0,42–0,45), prior weight in rounds. */
  SELLER_SHARE_PRIOR: 0.42,
  SELLER_SHARE_PRIOR_WEIGHT: 8,
  /** Survival table of the seller's reply time (hours). */
  KM_HOURS: [1, 3, 6, 12, 24, 48],
}

// ───────────────────────── src/core/profile.js ─────────────────────────
/**
 * The learned profile: small corrections, fitted every month on the user's own outcomes, that the engine adds to its
 * acceptance logits, plus two counter-engine parameters. Without a profile (web app, tests, first month) the engine
 * is unchanged.
 *
 *   logit' = logit + (slope − 1)·(logit − c) + intercept + time[group] + disc(discount)    (first offer, c = SLOPE_CENTER)
 *   logit' = logit + counter + time[group of the send window]                                       (our counter)
 *   counterShare     how much this user's sellers concede in a counter, relative to eBay's 0,42 (stance reading)
 *   sellerReplyHours how long they take to answer (availability during the wait), null = engine default
 *
 * disc(d) is piecewise linear through the knots at 10/20/30% and flat outside: never a step at a band edge.
 */
const ZERO_TIME = Object.freeze(Object.fromEntries(LEARNING_TIME_GROUPS.map((g) => [g.id, 0])))
const ZERO_DISC = Object.freeze(Object.fromEntries(LEARNING_DISCOUNT_KNOTS.map((k) => [k.id, 0])))

const DEFAULT_PROFILE = Object.freeze({
  version: 2,
  id: 'default',
  parentId: null,
  /** Parameters of the profile this one replaced (for the prequential rollback). */
  parent: null,
  month: null,
  createdAt: null,
  intercept: 0,
  slope: 1,
  time: ZERO_TIME,
  disc: ZERO_DISC,
  counter: 0,
  counterShare: 1,
  sellerReplyHours: null,
  discountPct: LEARNING.DEFAULT_DISCOUNT_PCT,
  /** Posterior covariance of the first-offer parameters (keys in `paramKeys`), for failure-risk intervals. */
  cov: null,
  paramKeys: null,
  changes: [],
  basedOn: 0,
  /** Prequential log Bayes factor against the parent, summed over the months this profile was active. */
  score: 0,
  scoreMonths: 0,
  /** Parameter families that may not move until the given month (after a rollback). */
  frozen: {},
})

const finite = (v, fallback) => (v != null && v !== '' && Number.isFinite(Number(v)) ? Number(v) : fallback)
const clampTo = (v, [lo, hi]) => Math.min(hi, Math.max(lo, v))

/** Hat weights of a discount on the three knots (sum to 1; flat below 10% and above 30%). */
function discKnotWeights(discountPct) {
  const d = finite(discountPct, 20)
  const ks = LEARNING_DISCOUNT_KNOTS
  const w = Object.fromEntries(ks.map((k) => [k.id, 0]))
  if (d <= ks[0].pct) w[ks[0].id] = 1
  else if (d >= ks[ks.length - 1].pct) w[ks[ks.length - 1].id] = 1
  else {
    for (let i = 0; i < ks.length - 1; i++) {
      if (d >= ks[i].pct && d <= ks[i + 1].pct) {
        const t = (d - ks[i].pct) / (ks[i + 1].pct - ks[i].pct)
        w[ks[i].id] = 1 - t
        w[ks[i + 1].id] = t
        break
      }
    }
  }
  return w
}

/** Nearest knot (for report tables). */
const discKnotOf = (discountPct) => {
  const d = finite(discountPct, 20)
  return d < 15 ? 'd10' : d < 25 ? 'd20' : 'd30'
}

const discOffset = (profile, discountPct) => {
  const w = discKnotWeights(discountPct)
  return Object.keys(w).reduce((s, id) => s + w[id] * finite(profile && profile.disc && profile.disc[id], 0), 0)
}

/**
 * Keeps the corrected acceptance non-increasing in the discount: between two knots the correction may rise by at most
 * 80% of what the engine's own curve falls over the same 10 points (scaled by the slope). Returns new knot values.
 */
function monotoneDisc(disc, slope = 1) {
  const ks = LEARNING_DISCOUNT_KNOTS
  const values = ks.map((k) => finite(disc && disc[k.id], 0))
  let worst = 0
  for (let i = 0; i < ks.length - 1; i++) {
    const limit = LEARNING.DISC_MONOTONE_MARGIN * (ks[i + 1].pct - ks[i].pct) * Math.max(0.1, slope) * LEARNING.DISC_MIN_ENGINE_SLOPE
    worst = Math.max(worst, (values[i + 1] - values[i]) / limit)
  }
  const scale = worst > 1 ? 1 / worst : 1
  return Object.fromEntries(ks.map((k, i) => [k.id, values[i] * scale]))
}

/** A stored profile (any version, possibly partial or tampered with) → a complete, bounded profile. */
function normalizeProfile(raw) {
  if (!raw || typeof raw !== 'object') return { ...DEFAULT_PROFILE }
  const B = LEARNING.BOUNDS
  const slope = clampTo(finite(raw.slope, 1), B.slope)
  const disc = monotoneDisc(Object.fromEntries(LEARNING_DISCOUNT_KNOTS.map((k) => [k.id, clampTo(finite(raw.disc && raw.disc[k.id], 0), B.disc)])), slope)
  const hours = raw.sellerReplyHours == null ? null : finite(raw.sellerReplyHours, null)
  return {
    ...DEFAULT_PROFILE,
    ...raw,
    version: 2,
    intercept: clampTo(finite(raw.intercept, 0), B.intercept),
    slope,
    time: Object.fromEntries(LEARNING_TIME_GROUPS.map((g) => [g.id, clampTo(finite(raw.time && raw.time[g.id], 0), B.time)])),
    disc,
    counter: clampTo(finite(raw.counter, 0), B.counter),
    counterShare: clampTo(finite(raw.counterShare, 1), B.share),
    sellerReplyHours: hours == null ? null : clampTo(hours, B.latency),
    discountPct: clampTo(finite(raw.discountPct, LEARNING.DEFAULT_DISCOUNT_PCT), B.discountPct),
    changes: Array.isArray(raw.changes) ? raw.changes : [],
    frozen: raw.frozen && typeof raw.frozen === 'object' ? raw.frozen : {},
    score: finite(raw.score, 0),
    scoreMonths: finite(raw.scoreMonths, 0),
  }
}

/** The tunable parameters only (what a rollback restores). */
const profileParams = (profile) => {
  const P = normalizeProfile(profile)
  return {
    intercept: P.intercept, slope: P.slope, time: { ...P.time }, disc: { ...P.disc }, counter: P.counter,
    counterShare: P.counterShare, sellerReplyHours: P.sellerReplyHours, discountPct: P.discountPct,
  }
}

const timeGroupOf = (windowId) => (LEARNING_TIME_GROUPS.find((g) => g.windows.includes(windowId)) || LEARNING_TIME_GROUPS[2]).id

/** True when the profile changes at least one estimate (a default or empty profile is a no-op). */
function profileIsActive(profile) {
  if (!profile) return false
  const off = (v, base = 0) => Math.abs(finite(v, base) - base) > 1e-9
  if (off(profile.intercept) || off(profile.slope, 1) || off(profile.counter) || off(profile.counterShare, 1)) return true
  if (profile.sellerReplyHours != null && Number.isFinite(Number(profile.sellerReplyHours))) return true
  return Object.values(profile.time || {}).some((v) => off(v)) || Object.values(profile.disc || {}).some((v) => off(v))
}

/**
 * The extra factor row for a first offer, or null when the profile is absent or changes nothing.
 * `logit` is the engine's logit before the correction (base + capped factors).
 */
function learnedOfferRow(profile, { logit, windowId, discountPct }) {
  if (!profileIsActive(profile)) return null
  const time = finite(profile.time && profile.time[timeGroupOf(windowId)], 0)
  const disc = discOffset(profile, discountPct)
  const weight = (finite(profile.slope, 1) - 1) * (logit - LEARNING.SLOPE_CENTER) + finite(profile.intercept, 0) + time + disc
  if (Math.abs(weight) < 1e-9) return null
  return { id: 'learned', group: 'learned', label: 'Correzione dai tuoi esiti', weight, rawWeight: weight, learned: { time, disc, intercept: finite(profile.intercept, 0), slope: finite(profile.slope, 1) } }
}

/** The extra factor row for our counter (seller accepts our number), or null. `windowId` is null for the lookahead. */
function learnedCounterRow(profile, { windowId }) {
  if (!profileIsActive(profile)) return null
  const time = windowId ? finite(profile.time && profile.time[timeGroupOf(windowId)], 0) : 0
  const weight = finite(profile.counter, 0) + time
  if (Math.abs(weight) < 1e-9) return null
  return { id: 'learned', group: 'learned', label: 'Correzione dai tuoi esiti', weight, rawWeight: weight, learned: { time, counter: finite(profile.counter, 0) } }
}

/** How much this user's sellers concede relative to the eBay mean (1 = as the engine assumes). */
const counterShareOf = (profile) => (profile ? clampTo(finite(profile.counterShare, 1), LEARNING.BOUNDS.share) : 1)

/** Hours the seller takes to answer, learned or the engine default. */
const sellerReplyHoursOf = (profile) => (profile && profile.sellerReplyHours != null && Number.isFinite(Number(profile.sellerReplyHours))
  ? clampTo(Number(profile.sellerReplyHours), LEARNING.BOUNDS.latency)
  : COUNTER.SELLER_REPLY_HOURS)

/** Default target discount for a listing read from a link: the learned one, else the engine default (−20%). */
const defaultDiscountFor = (profile) => Math.round(clampTo(finite(profile && profile.discountPct, LEARNING.DEFAULT_DISCOUNT_PCT), LEARNING.BOUNDS.discountPct))

// ───────────────────────── src/core/scoring.js ─────────────────────────
const findCategory = (id) => CATEGORIES.find((c) => c.id === id) || null
const findListingAge = (id) => LISTING_AGES.find((a) => a.id === id) || LISTING_AGES[0]
const findListingSignal = (id) => LISTING_SIGNALS.find((s) => s.id === id) || LISTING_SIGNALS[0]

/** Quantised to 1e-6 so that exact 15% / 30% / 40% offers on decimal prices do not drift across a band edge. */
const computeDiscountPct = (listPrice, targetPrice) =>
  listPrice > 0 ? Math.round(((listPrice - targetPrice) / listPrice) * 100 * 1e6) / 1e6 : 0

/** < 15% low · 15–30% (inclusive) medium · > 30% high */
const riskBandFor = (discountPct) => {
  if (discountPct < 15) return RISK_BANDS[0]
  if (discountPct <= 30) return RISK_BANDS[1]
  return RISK_BANDS[2]
}

const baseLogitFor = (discountPct) => interpolateLogit(BASE_CURVE, discountPct)

/* ───────── individual factors (logit units) ───────── */

const categoryWeight = (category) => (category ? category.weight : 0)

/** Premium categories punish, disposable ones tolerate, aggressive discounts. Ramps between 25% and 35%. */
const interactionWeight = (category, discountPct) => {
  if (!category) return 0
  const r = ramp(discountPct, 25, 35)
  if (category.premium) return -0.4 * r
  if (category.disposable) return 0.15 * r
  return 0
}

const gapWeight = (listPrice, targetPrice) => interpolate(GAP_CURVE, Math.max(0, listPrice - targetPrice))

const signalWeight = (signal) => (signal ? signal.weight : 0)

const ageCurve = (days) => interpolate(AGE_CURVE, days)

/**
 * Two components: the listing's age today, and how much the seller softens while we wait.
 * For an unknown age we assume nothing today and let waiting count half (capped).
 */
const ageWeights = (listingAge, category, daysWaited) => {
  const mult = category ? category.ageMultiplier : 1
  const today = listingAge.id === 'unknown' ? 0 : ageCurve(listingAge.days) * mult
  let wait = (ageCurve(listingAge.days + daysWaited) - ageCurve(listingAge.days)) * mult
  if (listingAge.id === 'unknown') wait = Math.min(0.15, wait * 0.5)
  return { today, wait }
}

/** Expert sellers accept small discounts gladly and refuse aggressive ones; ramps avoid cliffs. */
const sellerWeight = (sellerProfileId, discountPct) => {
  switch (sellerProfileId) {
    case 'new_seller':
      return 0.2
    case 'expert':
      if (discountPct <= 10) return 0.15
      if (discountPct <= 20) return 0.15 - 0.25 * ramp(discountPct, 10, 20)
      if (discountPct <= 25) return -0.1
      return -0.1 - 0.25 * ramp(discountPct, 25, 35)
    default:
      return 0
  }
}

/** Holidays behave like Sundays. */
const effectiveWeekday = (date) => (isItalianHoliday(date) ? 0 : date.getDay())

const timeWindowAt = (date) => {
  const day = effectiveWeekday(date)
  const minutes = minutesOfDay(date)
  const window = TIME_WINDOWS.find((w) => w.days.includes(day) && minutes >= w.from && minutes < w.to) || NEUTRAL_WINDOW
  if (day !== date.getDay() && HOLIDAY_WINDOW_LABELS[window.id]) {
    return { ...window, label: HOLIDAY_WINDOW_LABELS[window.id], why: HOLIDAY_WINDOW_WHY, holiday: true }
  }
  return window
}

/** Inactive sellers read the offer at a random moment: timing barely matters for them. */
const timeWeight = (window, sellerProfileId) =>
  window.weight * (sellerProfileId === 'inactive' ? INACTIVE_TIME_DAMPING : 1)

/** Month-end effect anchored to the last day (short months shift earlier), with ramps instead of cliffs. */
const monthWindowAt = (date) => {
  const day = date.getDate()
  const daysToEnd = daysInMonth(date) - day
  if (daysToEnd <= 6) return { ...MONTH_WINDOWS.end, weight: MONTH_END_WEIGHT }
  if (daysToEnd <= 13) return { ...MONTH_WINDOWS.late, weight: MONTH_END_WEIGHT * (1 - (daysToEnd - 6) / 7) }
  if (day <= 5) return { ...MONTH_WINDOWS.start, weight: MONTH_START_WEIGHT }
  if (day <= 8) return { ...MONTH_WINDOWS.start, weight: MONTH_START_WEIGHT * (1 - (day - 5) / 3) }
  return { ...MONTH_WINDOWS.mid, weight: 0 }
}

/* ───────── full score at a given send moment ───────── */

/**
 * Scores the offer if sent at `sendDate`, `daysWaited` days from now.
 * Returns the base logit, the (capped) factor list in a fixed order, the total logit and pAccept.
 */
function scoreAt(input, sendDate, daysWaited = 0) {
  const { discountPct, category, listingAge, sellerProfile, listingSignal, listPrice, targetPrice } = input
  const base = baseLogitFor(discountPct)
  const timeWindow = timeWindowAt(sendDate)
  const monthWindow = monthWindowAt(sendDate)
  const age = ageWeights(listingAge, category, daysWaited)

  const raw = [
    { id: 'category', group: 'category', label: category ? `Categoria ${category.label.toLowerCase()}` : 'Categoria', weight: categoryWeight(category) },
    { id: 'interaction', group: 'category', label: category && category.premium ? 'Sconto alto su categoria di valore' : 'Categoria tollerante agli sconti alti', weight: interactionWeight(category, discountPct) },
    { id: 'gap', group: 'price', label: `Differenza di ${Math.round(listPrice - targetPrice)} €`, weight: gapWeight(listPrice, targetPrice) },
    { id: 'signal', group: 'signal', label: listingSignal.id === 'none' ? 'Testo annuncio' : `Annuncio: ${listingSignal.label.toLowerCase()}`, weight: signalWeight(listingSignal) },
    { id: 'age', group: 'age', label: listingAge.id === 'unknown' ? 'Anzianità non indicata' : `Annuncio ${listingAge.label.toLowerCase()}`, weight: age.today },
    { id: 'wait', group: 'age', label: daysWaited > 0 ? `Attesa di ${daysWaited} ${daysWaited === 1 ? 'giorno' : 'giorni'}` : 'Nessuna attesa', weight: age.wait },
    { id: 'seller', group: 'seller', label: sellerLabel(sellerProfile), weight: sellerWeight(sellerProfile, discountPct) },
    { id: 'time', group: 'time', label: timeWindow.label, weight: timeWeight(timeWindow, sellerProfile), window: timeWindow },
    { id: 'month', group: 'month', label: monthWindow.label, weight: monthWindow.weight, window: monthWindow },
  ]

  // Cap the stacked modifiers so that extreme combinations stay plausible.
  const sumPos = raw.filter((f) => f.weight > 0).reduce((s, f) => s + f.weight, 0)
  const sumNeg = raw.filter((f) => f.weight < 0).reduce((s, f) => s + f.weight, 0)
  const posScale = sumPos > POSITIVE_CAP ? POSITIVE_CAP / sumPos : 1
  const negScale = sumNeg < NEGATIVE_CAP ? NEGATIVE_CAP / sumNeg : 1
  const factors = raw.map((f) => ({ ...f, rawWeight: f.weight, weight: f.weight > 0 ? f.weight * posScale : f.weight * negScale }))

  const total = base + factors.reduce((s, f) => s + f.weight, 0)
  // The learned correction (monthly profile) comes after the caps: it measures how this user's sellers really answer.
  const learned = learnedOfferRow(input.profile, { logit: total, windowId: timeWindow.id, discountPct })
  const logit = learned ? total + learned.weight : total
  return {
    base,
    logit,
    rawLogit: total,
    learnedWeight: learned ? learned.weight : 0,
    pAccept: squash(logit),
    pBase: squash(base),
    factors: learned ? [...factors, learned] : factors,
    capped: posScale < 1 || negScale < 1,
    timeWindow,
    monthWindow,
    ageDays: listingAge.days + daysWaited,
  }
}

const sellerLabel = (id) =>
  ({ new_seller: 'Venditore nuovo', expert: 'Venditore esperto', inactive: 'Venditore inattivo' })[id] || 'Venditore non indicato'

/**
 * Sequential attribution in the fixed factor order: each row is the probability
 * change when that factor is added on top of the previous ones, so rows sum
 * exactly to pAccept − pBase (rounding drift is folded into the biggest row).
 */
function attributeFactors(score) {
  let running = score.base
  let prev = squash(running)
  const rows = []
  for (const f of score.factors) {
    if (f.weight === 0 && f.group !== 'time' && f.group !== 'month') continue
    running += f.weight
    const p = squash(running)
    rows.push({ ...f, deltaPoints: Math.round((p - prev) * 100) })
    prev = p
  }
  const basePct = Math.round(score.pBase * 100)
  const totalPct = Math.round(score.pAccept * 100)
  const drift = totalPct - basePct - rows.reduce((s, r) => s + r.deltaPoints, 0)
  if (drift !== 0 && rows.length) {
    const idx = rows.reduce((best, r, i) => (Math.abs(r.deltaPoints) > Math.abs(rows[best].deltaPoints) ? i : best), 0)
    rows[idx].deltaPoints += drift
  }
  return { basePct, totalPct, rows }
}

/* ───────── risk of a blunt refusal or block (separate from acceptance) ───────── */

function blockRiskAt(input, sendDate) {
  const { discountPct, category, sellerProfile, listingSignal } = input
  const reasons = []
  let score = 0
  const aggressive = 2 * ramp(discountPct, 27, 33)
  if (aggressive > 0) {
    score += aggressive
    reasons.push(discountPct > 30 ? 'Sconto oltre il 30%' : 'Sconto a ridosso del 30%')
  }
  if (discountPct >= 38) {
    score += 0.5
    reasons.push('Sconto al limite consentito da Vinted')
  }
  if (category && category.premium) {
    score += 1
    reasons.push('Categoria di valore: il venditore conosce il prezzo')
  }
  if (listingSignal && listingSignal.blockScore) {
    score += listingSignal.blockScore
    reasons.push('L\'annuncio dice "prezzo non trattabile"')
  }
  if (sellerProfile === 'new_seller') {
    score += 0.5
    reasons.push('Venditore alle prime vendite: può reagire d\'impulso')
  }
  if (sellerProfile === 'expert') score -= 0.5
  const w = timeWindowAt(sendDate)
  if (w.weight < 0) {
    score += 2 * -w.weight
    reasons.push(`Invio in una fascia sfavorevole (${w.label.toLowerCase()})`)
  }
  const level = score < 1 ? 'low' : score < 2.5 ? 'medium' : 'high'
  const labels = { low: 'Basso', medium: 'Medio', high: 'Alto' }
  return { level, label: labels[level], score, reasons }
}

/** ± percentage points of uncertainty from the optional inputs left blank. */
function uncertaintyFor(input) {
  let unknowns = 0
  if (input.listingAge.id === 'unknown') unknowns++
  if (!input.sellerProfile || input.sellerProfile === 'unknown') unknowns++
  return clamp(unknowns * UNCERTAINTY_PER_UNKNOWN, 0, UNCERTAINTY_MAX)
}

// ───────────────────────── src/core/scheduler.js ─────────────────────────
/* ───────── availability & response ───────── */

/** Daily probability that the item sells to someone else on day `j` from now. */
const hazardAt = (input, j) => {
  const rate = input.category ? input.category.dailySellRate : 0.015
  return rate * ageHazardMultiplier(input.listingAge.days + j)
}

/** Probability that the item is still available after `days` days. */
const availabilityAfter = (input, days) => {
  let p = 1
  for (let j = 0; j < days; j++) p *= 1 - hazardAt(input, j)
  return p
}

/** Probability that the seller even opens the offer before it lapses. */
const readProbability = (input) => (input.sellerProfile === 'inactive' ? INACTIVE_READ_PROBABILITY : 1)

/** Days ahead worth considering: stop when the item would likely be gone; stale listings do not justify long waits. */
function horizonFor(input) {
  let k = 0
  while (k < HORIZON_MAX_DAYS && availabilityAfter(input, k + 1) >= HORIZON_AVAILABILITY_FLOOR) k++
  let horizon = Math.max(HORIZON_MIN_DAYS, Math.min(HORIZON_MAX_DAYS, k))
  if (input.listingAge.id === 'over_month') horizon = Math.min(horizon, HORIZON_STALE_LISTING_DAYS)
  return horizon
}

/* ───────── candidate moments ───────── */

/** Deterministic per-offer minute offset so that different items do not all land on 21:45. */
const jitterFor = (input) => {
  const key = [input.category && input.category.id, input.listPrice, input.targetPrice, input.listingAge.id, input.sellerProfile, input.listingSignal.id].join('|')
  return JITTER_MINUTES[hashString(key) % JITTER_MINUTES.length]
}

/**
 * Enumerates candidate send moments: "now" (always, with its true window weight)
 * plus the canonical evening/weekend slots of each day up to the horizon.
 */
function buildCandidateSlots(input, now, horizonDays) {
  const nowDate = ceilToMinutes(addMinutes(now, 5), 5)
  const nowSlot = { date: nowDate, daysWaited: calendarDaysBetween(now, nowDate), kind: 'now', windowId: timeWindowAt(nowDate).id }
  const slots = [nowSlot]
  const jitter = jitterFor(input)
  const today = startOfDay(now)
  for (let k = 0; k <= horizonDays; k++) {
    const day = addDays(today, k)
    const times = CANONICAL_SLOTS[effectiveWeekday(day)] || []
    for (const [hh, mm] of times) {
      const canonical = atTime(day, hh, mm)
      let date = atTime(day, hh, mm + jitter)
      if (timeWindowAt(date).id !== timeWindowAt(canonical).id) date = canonical
      if (date.getTime() <= now.getTime()) continue
      const windowId = timeWindowAt(date).id
      if (isSameDay(date, nowDate) && windowId === nowSlot.windowId) continue
      slots.push({ date, daysWaited: k, kind: 'canonical', windowId })
    }
  }
  return slots
}

function evaluateSlot(input, slot) {
  const score = scoreAt(input, slot.date, slot.daysWaited)
  const pAvailable = availabilityAfter(input, slot.daysWaited)
  const pRead = readProbability(input)
  const pOverall = score.pAccept * pAvailable * pRead
  const utility = pOverall * Math.pow(IMPATIENCE_PER_DAY, slot.daysWaited)
  return { ...slot, score, pAvailable, pRead, pOverall, utility, expiresAt: addMinutes(slot.date, VINTED.OFFER_VALIDITY_HOURS * 60) }
}

/* ───────── choice ───────── */

const byUtilityThenDate = (a, b) => b.utility - a.utility || a.date - b.date

/**
 * Chooses the moment to recommend. Among near-ties (within 1.5pp or 3% of the
 * best utility) the earliest wins, so the verdict does not flip by weeks on noise.
 */
function pickMoments(input, now, { preferredSendAt = null, exactSendAt = null } = {}) {
  const horizon = horizonFor(input)
  const evaluated = buildCandidateSlots(input, now, horizon).map((s) => evaluateSlot(input, s))
  // "Now" competes only when neither the current instant nor the +5 min send moment sits in an unfavourable window.
  const nowIsFavourable = timeWindowAt(now).weight >= 0
  const eligible = evaluated.filter((s) => s.kind !== 'now' || (nowIsFavourable && s.score.timeWindow.weight >= 0))
  const ranking = [...eligible].sort(byUtilityThenDate)
  const best = ranking[0]
  const threshold = best.utility - Math.max(NEAR_TIE_ABS, NEAR_TIE_REL * best.utility)
  let chosen = [...eligible.filter((s) => s.utility >= threshold)].sort((a, b) => a.date - b.date)[0]
  // The caller (e.g. the optimizer's "Applica") may pin a specific moment: use the nearest candidate within 3 hours.
  let pinned = false
  if (preferredSendAt) {
    const wanted = new Date(preferredSendAt).getTime()
    const nearest = [...eligible].sort((a, b) => Math.abs(a.date.getTime() - wanted) - Math.abs(b.date.getTime() - wanted))[0]
    if (nearest && Math.abs(nearest.date.getTime() - wanted) <= 3 * 3_600_000) {
      chosen = nearest
      pinned = true
    }
  }
  // An exact moment (the learning loop's flagged ±1 h variation) is scored as its own slot and always chosen.
  if (exactSendAt) {
    const exactDate = ceilToMinutes(new Date(exactSendAt), 5)
    if (Number.isFinite(exactDate.getTime()) && exactDate.getTime() > now.getTime()) {
      chosen = evaluateSlot(input, { date: exactDate, daysWaited: calendarDaysBetween(now, exactDate), kind: 'canonical', exact: true, windowId: timeWindowAt(exactDate).id })
      pinned = true
    }
  }
  // A strictly better slot (any day, even later the same evening) is reported alongside the recommendation.
  const alsoGood = best !== chosen && best.utility > chosen.utility ? best : null

  const nowSlot = evaluated.find((s) => s.kind === 'now')
  const nowEligible = eligible.includes(nowSlot)
  const closeEnough = nowSlot.pOverall >= chosen.pOverall - SEND_NOW_TOLERANCE
  const sendNow = {
    slot: nowSlot,
    ok: chosen.kind === 'now' || (nowEligible && closeEnough),
    reason: chosen.kind === 'now' ? 'chosen' : !nowEligible ? 'avoid_window' : closeEnough ? 'close_enough' : 'worse',
    deltaPoints: Math.round((nowSlot.pOverall - chosen.pOverall) * 100),
    window: nowSlot.score.timeWindow,
    windowEndsAt: addMinutes(startOfDay(nowSlot.date), nowSlot.score.timeWindow.to),
  }

  const hoursToChosen = (chosen.date.getTime() - now.getTime()) / 3_600_000
  const quick = hoursToChosen > QUICK_ALTERNATIVE_MIN_HOURS
    ? [...eligible.filter((s) => s.kind !== 'now' && s.daysWaited < chosen.daysWaited && s.date.getTime() - now.getTime() <= 48 * 3_600_000)].sort(byUtilityThenDate)[0] || null
    : null

  // Best slot per distinct day, excluding "now" and the days already shown (chosen, alsoGood, quick); listed chronologically.
  const seenDays = new Set([chosen, alsoGood, quick].filter(Boolean).map((s) => startOfDay(s.date).getTime()))
  const alternatives = []
  for (const s of ranking) {
    const key = startOfDay(s.date).getTime()
    if (seenDays.has(key) || s.kind === 'now') continue
    seenDays.add(key)
    alternatives.push(s)
    if (alternatives.length >= 3) break
  }
  alternatives.sort((a, b) => a.date - b.date)

  const topDays = [chosen, ...(alsoGood ? [alsoGood] : []), ...alternatives].slice(0, 5).map((s) => s.pOverall)
  const spread = Math.max(...topDays) - Math.min(...topDays)
  const maxAccept = Math.max(...evaluated.map((s) => s.score.pAccept))

  return { horizon, chosen, best, alsoGood, quick, alternatives, nowSlot, sendNow, ranking, eligible, spread, timingMatters: spread >= TIMING_MATTERS_SPREAD, maxAccept, pinned }
}

/* ───────── windows to avoid ───────── */

const describeWindow = (w) => ({
  id: w.id,
  label: w.label,
  weight: w.weight,
  rangeLabel: formatRange(w.from, w.to),
  daysLabel: formatDayList(w.days),
  why: w.why,
})

/** All negative windows, worst first. */
const avoidWindows = () => TIME_WINDOWS.filter((w) => w.weight < 0).sort((a, b) => a.weight - b.weight).map(describeWindow)

/** Negative windows that apply on the given day, worst first. */
const avoidWindowsOn = (date) => {
  const day = effectiveWeekday(date)
  return TIME_WINDOWS.filter((w) => w.weight < 0 && w.days.includes(day)).sort((a, b) => a.weight - b.weight || a.from - b.from).map(describeWindow)
}

// ───────────────────────── src/core/messages.js ─────────────────────────
/**
 * Supporting message templates (Italian). Pure data + formatting, no UI.
 * Rules baked in: "Ciao" + tu register, never criticise the item or the price,
 * never compare with other listings, the offer itself is sent through Vinted's button.
 */

const TONES = [
  { id: 'cordiale', label: 'Cordiale', hint: 'Rompe il ghiaccio e lascia spazio a una controproposta' },
  { id: 'diretto', label: 'Diretto', hint: 'Breve e senza giri di parole; con sconti piccoli l\'offerta può partire anche senza messaggio' },
  { id: 'impegno', label: 'Impegno all\'acquisto', hint: 'Toglie al venditore la paura dell\'offerta accettata e mai pagata' },
  { id: 'motivato', label: 'Motivato', hint: 'Dà un motivo (il budget) senza criticare l\'articolo: adatto a categorie di valore' },
]

const recommendedToneFor = (input) => {
  if (input.category && input.category.premium) return 'motivato'
  if (input.riskBand.id === 'low') return 'diretto'
  if (input.riskBand.id === 'medium') return 'cordiale'
  return 'impegno'
}

const formatEuro = (value) => {
  const rounded = Math.round(value * 100) / 100
  const hasCents = Math.abs(rounded - Math.round(rounded)) > 0.004
  const str = hasCents ? rounded.toFixed(2).replace('.', ',') : String(Math.round(rounded))
  return `${str} €`
}

const salutationFor = (sendAt) => {
  if (!sendAt) return ''
  const hour = sendAt.getHours()
  if (hour < 12) return 'buona giornata'
  if (hour >= 17) return 'buona serata'
  return ''
}

const closing = (sendAt) => {
  const s = salutationFor(sendAt)
  return s ? `Grazie e ${s}!` : 'Grazie!'
}

/**
 * `beforeOffer` = true when the strategy is to write first and send the offer only after a reply
 * (high block risk or inactive seller): the templates then propose the price instead of announcing a sent offer.
 */
function buildMessages({ itemTitle, targetPrice, listingAge, sendAt, beforeOffer = false }) {
  const item = itemTitle && itemTitle.trim() ? `"${itemTitle.trim()}"` : "l'articolo"
  const Item = item === "l'articolo" ? "L'articolo" : item
  const price = formatEuro(targetPrice)
  const isOld = listingAge && (listingAge.id === 'over_month' || listingAge.id === 'weeks_2_4')

  if (beforeOffer) {
    return [
      {
        tone: 'cordiale',
        text: `Ciao! Mi piace molto ${item}. Ti andrebbe bene ${price}? Se per te può andare ti invio subito l'offerta e completo l'acquisto. ${closing(sendAt)}`,
      },
      {
        tone: 'diretto',
        text: `Ciao! Ti propongo ${price} per ${item}. Se per te va bene ti invio subito l'offerta. Grazie!`,
      },
      {
        tone: 'impegno',
        text: `Ciao! ${isOld ? 'Ho visto che ' + item + ' è online da un po\': ' : ''}ti propongo ${price}. Se accetti ti invio l'offerta e completo subito l'acquisto, così puoi spedire appena ti è comodo. ${closing(sendAt)}`,
      },
      {
        tone: 'motivato',
        text: `Ciao! ${Item} mi interessa davvero: potrei arrivare a ${price}, che è il massimo del mio budget in questo momento. Se per te può andare ti invio subito l'offerta. ${closing(sendAt)}`,
      },
    ]
  }

  return [
    {
      tone: 'cordiale',
      text: `Ciao! Mi piace molto ${item} e ti ho appena inviato un'offerta di ${price}. Se per te può andare confermo subito, altrimenti dimmi pure la tua cifra. ${closing(sendAt)}`,
    },
    {
      tone: 'diretto',
      text: `Ciao! Ti ho inviato un'offerta di ${price} per ${item}. Se va bene per te completo subito l'acquisto. Grazie!`,
    },
    {
      tone: 'impegno',
      text: `Ciao! Ti ho appena inviato un'offerta di ${price} per ${item}. ${isOld ? 'Ho visto che è online da un po\': se' : 'Se'} accetti completo subito l'acquisto, così puoi spedire appena ti è comodo e senza altre trattative. ${closing(sendAt)}`,
    },
    {
      tone: 'motivato',
      text: `Ciao! ${Item} mi interessa davvero e ti ho inviato un'offerta di ${price}: è il massimo del mio budget in questo momento. Se per te può andare completo subito l'acquisto. ${closing(sendAt)}`,
    },
  ]
}

/* ───────── counter-offer messages (our reply to the seller's "Fai il tuo prezzo") ───────── */

/**
 * Rules (enforced by tests): start with "Ciao!", "tu" register, never repeat the seller's number, never criticise the
 * item, give a real reason (the total with the Vinted fee) and promise to pay at once, "metà strada" only for a split,
 * "massimo" only for a final offer, no deadlines or threats. First person without past participles that agree with
 * the writer's gender ("ho alzato", not "sono salito"). Coherent with the first-offer "motivato" template, which
 * already called the first offer the top of the budget: counters say "Ho rifatto i conti".
 */
function buildCounterMessages({ itemTitle, price, previousOffer, firstOffer, sendAt, isSplit = false, isFinal = false, stale = false, total }) {
  const item = itemTitle && itemTitle.trim() ? `"${itemTitle.trim()}"` : "l'articolo"
  const p = formatEuro(price)
  const prev = formatEuro(previousOffer)
  const first = formatEuro(firstOffer ?? previousOffer)
  const tot = formatEuro(total ?? price)
  const end = closing(sendAt)
  const hi = stale ? 'Ciao! Scusa se ti rispondo solo ora.' : 'Ciao!'

  let texts
  if (isFinal) {
    const mid = isSplit ? ' a metà strada,' : ''
    texts = {
      cordiale: `${hi} Ci ho pensato bene: per ${item} posso arrivare${mid} a ${p}: è il massimo che riesco a fare. Se ti va bene lo compro subito; in ogni caso grazie!`,
      diretto: `${hi} ${isSplit ? `Facciamo a metà strada: ${p}` : p} è il massimo che posso fare per ${item}: se ti va, lo compro subito. Grazie!`,
      impegno: `${hi} Ultimo passo da parte mia${isSplit ? ', a metà strada' : ''}: ${p}, il massimo che posso spendere. Se accetti pago subito. Grazie comunque della disponibilità!`,
      motivato: `${hi} Ci ho pensato bene: per ${item} posso arrivare${mid} a ${p}, che con la commissione Vinted diventa circa ${tot}, ed è davvero il massimo che riesco a spendere. Se ti va bene lo compro subito; in ogni caso grazie della disponibilità!`,
    }
  } else if (isSplit) {
    texts = {
      cordiale: `${hi} Grazie per la risposta. Che ne dici se ci veniamo incontro a metà strada, a ${p}? Se ti va bene lo compro subito. ${end}`,
      diretto: `${hi} Facciamo a metà strada? ${p} e lo compro subito. Grazie!`,
      impegno: `${hi} Grazie per la risposta. Ho già alzato la mia offerta rispetto a ${first}: facciamo a metà strada? Ti propongo ${p} e, se accetti, lo compro subito, così puoi spedire quando ti è comodo. ${end}`,
      motivato: `${hi} Ho rifatto i conti: facciamo a metà strada a ${p}? Con la commissione Vinted per me diventa già circa ${tot}. Se ti va bene lo compro subito. ${end}`,
    }
  } else {
    texts = {
      cordiale: `${hi} Grazie per la risposta, ${item} mi piace davvero. Mi chiedevo se ${p} potesse andarti bene: se sì, lo compro subito. ${end}`,
      diretto: `${hi} Ti propongo ${p} per ${item}: se ti va bene lo compro subito. Grazie!`,
      impegno: `${hi} Ti propongo ${p} per ${item}. Se accetti pago subito, così puoi spedire quando ti è comodo. ${end}`,
      motivato: `${hi} Grazie per la risposta. Ho rifatto i conti e ho alzato la mia offerta da ${prev} a ${p}: con la commissione Vinted per me diventa già circa ${tot}. Mi chiedevo se così potesse andarti bene: se sì, lo compro subito. ${end}`,
    }
  }
  return TONES.map((t) => ({ tone: t.id, text: texts[t.id] }))
}

/** Messages when the plan is to buy at the seller's price ("Acquista"): optional, they only close on a friendly note. */
function buildAcceptMessages({ stale = false } = {}) {
  const hi = stale ? 'Ciao! Scusa se ti rispondo solo ora.' : 'Ciao!'
  const texts = {
    cordiale: `${hi} Affare fatto, lo compro subito. Grazie!`,
    diretto: `${hi} Va bene, lo compro subito. Grazie!`,
    impegno: `${hi} Affare fatto: lo compro adesso e pago subito. Grazie!`,
    motivato: `${hi} Grazie della disponibilità: lo compro subito.`,
  }
  return TONES.map((t) => ({ tone: t.id, text: texts[t.id] }))
}

/** A nudge after a day of silence: no new number, only a reminder that our offer is waiting. */
const buildCounterNudge = ({ itemTitle }) => {
  const item = itemTitle && itemTitle.trim() ? `"${itemTitle.trim()}"` : "l'articolo"
  return `Ciao! Ti ho fatto una proposta per ${item}: quando hai un momento fammi sapere. Grazie!`
}

/** Final offer → reason (motivato); split → payment promise (impegno); tough seller or valuable item → motivato. */
const recommendedCounterToneFor = ({ isSplit = false, isFinal = false, stance = null, premium = false }) => {
  if (isFinal) return 'motivato'
  if (isSplit) return 'impegno'
  if (premium || stance === 'firm' || stance === 'hold') return 'motivato'
  return 'cordiale'
}

// ───────────────────────── src/core/reasoning.js ─────────────────────────
const roundPct = (v) => Math.round(v)

/** Italian partitive article before a number: "dell'8%", "dell'11%", "dell'80%", "dello 0%", otherwise "del 25%". */
const articleFor = (n) => {
  const r = Math.round(n)
  if (r === 0) return 'dello '
  return r === 1 || r === 8 || r === 11 || (r >= 80 && r <= 89) ? "dell'" : 'del '
}

const dayPart = (date) => {
  const hour = date.getHours()
  if (hour >= 17) return 'sera'
  if (hour < 12) return 'mattina'
  return 'pomeriggio'
}

/**
 * The verdict sentence, with a fixed grammar by distance in days:
 * now → "adesso", today → "stasera/oggi alle ore", tomorrow → "domani sera, lunedì 5 ottobre, alle ore",
 * later → "giovedì 29 ottobre alle ore 21:45" + "tra 5 giorni".
 */
function buildVerdict(chosen, sendNow, now, best = null, { subject = "l'offerta" } = {}) {
  const lead = `Invia ${subject}`
  const k = calendarDaysBetween(now, chosen.date)
  const time = formatTime(chosen.date)
  const dateLabel = formatLongDate(chosen.date, now)
  const window = chosen.score.timeWindow
  const windowLabel = window.range ? `tra le ${window.range.replace('–', ' e le ')}, ideale ${time}` : `alle ${time}`
  const expiresLabel = `${formatLongDate(chosen.expiresAt, now)} alle ${formatTime(chosen.expiresAt)}`

  let headline
  let sublabel
  if (chosen.kind === 'now') {
    headline = `${lead} adesso`
    const gain = best && best !== chosen ? Math.round((best.pOverall - chosen.pOverall) * 100) : 0
    if (window.weight > 0 && ['S', 'A', 'B'].includes(window.tier)) {
      sublabel = `Sei nella finestra giusta: dura fino alle ${formatTime(sendNow.windowEndsAt)}`
    } else if (gain >= 1 && best) {
      const when = isSameDay(best.date, chosen.date) ? `alle ${formatTime(best.date)}` : `${formatLongDate(best.date, now)} alle ${formatTime(best.date)}`
      sublabel = `Aspettare ${when} varrebbe al massimo ${gain} ${gain === 1 ? 'punto' : 'punti'} in più: non vale il rischio`
    } else if (window.weight > 0) {
      sublabel = 'Fascia accettabile: le finestre migliori sono in tarda serata, ma aspettare cambia poco'
    } else {
      sublabel = 'Aspettare non migliorerebbe le probabilità'
    }
  } else if (k === 0) {
    headline = `${lead} ${chosen.date.getHours() >= 17 ? 'stasera' : 'oggi'} alle ore ${time}`
    sublabel = capitalize(dateLabel)
  } else if (k === 1) {
    // The day part follows the window's own name when it has one ("Domenica mattina" → "domani mattina").
    const part = /morning/.test(window.id) ? 'mattina' : /afternoon/.test(window.id) ? 'pomeriggio' : dayPart(chosen.date)
    headline = `${lead} domani ${part}, ${dateLabel}, alle ore ${time}`
    sublabel = 'Domani'
  } else {
    headline = `${lead} ${dateLabel} alle ore ${time}`
    sublabel = capitalize(formatRelativeDay(chosen.date, now))
  }

  // `action` is the headline without "Invia <subject> ", for UIs that compose their own sentence.
  const action = headline.slice(lead.length + 1)
  return { headline, action, sublabel, when: formatRelativeDay(chosen.date, now), dateLabel, timeLabel: time, windowLabel, expiresLabel, isHoliday: isItalianHoliday(chosen.date) }
}

/** Opening sentence keyed by risk band (and by whether timing actually moves the needle). */
function openingSentence(input, timingMatters = true) {
  const d = roundPct(input.discountPct)
  const art = articleFor(d)
  if (input.riskBand.id === 'low') return `Sconto contenuto ${art}${d}%: quasi ogni fascia serale funziona, quindi conta soprattutto la rapidità.`
  if (input.riskBand.id === 'medium') return `Sconto ${art}${d}%, zona negoziabile: serve un momento in cui il venditore è rilassato e poco difensivo.`
  if (!timingMatters) return `Sconto aggressivo ${art}${d}%: le probabilità restano basse in qualunque fascia, quindi conta più il prezzo del tempismo.`
  return `Sconto aggressivo ${art}${d}%: serve tempismo perfetto, con la minima resistenza possibile da parte del venditore.`
}

/** One sentence, built once, for the "timing barely matters" case. */
function buildTimingNote(moments, chosen) {
  if (moments.timingMatters) return null
  const n = Math.max(1, Math.round(moments.spread * 100))
  return `Qui il tempismo pesa poco (circa ${n} ${n === 1 ? 'punto' : 'punti'} tra le finestre migliori): ${chosen.kind === 'now' ? 'puoi inviare adesso' : 'la prima buona fascia va bene'}.`
}

/**
 * Up to three complete sentences explaining the biggest drivers of the chosen moment.
 */
function buildReasons(input, chosen, attribution) {
  const { category, listingAge, sellerProfile, listingSignal, listPrice, targetPrice } = input
  const k = chosen.daysWaited
  const sentences = []
  const rows = [...attribution.rows].sort((a, b) => Math.abs(b.deltaPoints) - Math.abs(a.deltaPoints))

  for (const row of rows) {
    if (sentences.length >= 3) break
    const positive = row.deltaPoints > 0
    let text = null
    switch (row.id) {
      case 'time':
        text = chosen.score.timeWindow.why
        break
      case 'month':
        if (row.weight > 0) text = chosen.score.monthWindow.why
        else if (row.weight < 0) text = k <= 1
          ? 'Siamo a inizio mese, quando il venditore è meno pressato: per questo non conviene rinviare oltre.'
          : 'Siamo a inizio mese, quando il venditore è meno pressato: aspettare ancora non cambierebbe il quadro.'
        break
      case 'age':
        if (listingAge.id === 'today') text = 'L\'annuncio è appena stato pubblicato: il venditore è ancora ottimista sul prezzo.'
        else if (positive) text = `L'annuncio è online da ${listingAge.label.toLowerCase().replace(' fa', '')}: il venditore vuole liberarsi dell'invenduto e la finestra ottimale si anticipa.`
        else if (row.weight < 0) text = 'L\'annuncio è recente: il venditore non ha ancora motivo di cedere sul prezzo.'
        break
      case 'wait':
        if (positive && k >= 2) text = `Aspettare ${k} giorni lascia sgonfiare l'ottimismo iniziale del venditore.`
        break
      case 'category':
        if (!category) break
        if (category.id === 'kids') text = 'Nei vestiti per bambini il venditore vuole soprattutto fare spazio e accetta più volentieri.'
        else if (category.disposable) text = 'Nel fast fashion il venditore vuole liberarsi del capo e accetta più volentieri.'
        else if (category.premium) text = `${category.label}: il venditore conosce il valore di ciò che vende e negozia lentamente.`
        else if (category.id === 'electronics') text = 'Elettronica: il venditore confronta con il prezzo del nuovo e cede poco.'
        break
      case 'interaction':
        if (row.weight < 0) text = 'Su una categoria di valore uno sconto così alto viene letto come un affronto.'
        else if (row.weight > 0) text = 'In questa categoria anche uno sconto alto viene preso in considerazione.'
        break
      case 'gap':
        if (positive) text = `In euro chiedi solo ${Math.round(listPrice - targetPrice)} € in meno: per il venditore pesa poco.`
        else if (row.weight < 0) text = `In euro la differenza è di ${Math.round(listPrice - targetPrice)} €: il venditore ragiona anche in valore assoluto.`
        break
      case 'signal':
        if (listingSignal.id === 'fixed_price') text = 'L\'annuncio dice "prezzo non trattabile": ogni offerta parte in salita.'
        else if (listingSignal.id === 'open_to_offers') text = 'L\'annuncio invita a fare offerte: il venditore si aspetta una trattativa.'
        else if (listingSignal.id === 'clearing_out') text = 'Il venditore sta svuotando l\'armadio e vuole chiudere in fretta.'
        break
      case 'seller':
        if (sellerProfile === 'new_seller') text = 'Un venditore nuovo vuole le prime recensioni e accetta più volentieri, ma può reagire d\'impulso.'
        else if (sellerProfile === 'expert') text = positive ? 'Un venditore esperto chiude volentieri gli sconti ragionevoli.' : 'Un venditore esperto conosce il mercato e rifiuta gli sconti aggressivi.'
        else if (sellerProfile === 'inactive') text = 'Il venditore è inattivo: la priorità è farsi leggere, più del tempismo perfetto.'
        break
      default:
        break
    }
    if (text && !sentences.includes(text)) sentences.push(text)
  }
  if (sellerProfile === 'inactive' && !sentences.some((s) => s.startsWith('Il venditore è inattivo'))) {
    sentences.splice(Math.min(2, sentences.length), 0, 'Il venditore è inattivo: la priorità è farsi leggere, più del tempismo perfetto.')
  }
  return sentences.slice(0, 3)
}

function buildTips({ input, blockRisk, twoStep, chosen, now, messageBeforeOffer }) {
  const tips = []
  const { riskBand, discountPct, sellerProfile, listingAge, targetPrice, listPrice } = input

  tips.push(`Conta su circa ${VINTED.OFFER_VALIDITY_HOURS} ore per la risposta (Vinted non indica una scadenza ufficiale) e ricorda che puoi fare al massimo ${VINTED.OFFERS_PER_DAY} offerte al giorno: usa la prima nel momento giusto.`)
  if (discountPct < 5) {
    tips.push('Sconto quasi simbolico: valuta di comprare a prezzo pieno o di chiedere la spedizione inclusa invece di un\'offerta.')
  }
  if (twoStep) {
    tips.push(`Strategia a due step: apri a ${twoStep.openingPrice} €, lascia che il venditore controproponga e chiudi intorno a ${Math.round(targetPrice)} €.`)
  }
  if (messageBeforeOffer) {
    tips.push(blockRisk.level === 'high'
      ? 'Rischio di reazione brusca alto: manda prima il messaggio e invia l\'offerta solo dopo la risposta.'
      : 'Prima dell\'offerta scrivi un messaggio breve: i messaggi non scadono e ti dicono se il venditore è ancora attivo.')
  } else if (listingAge.days >= 7 && chosen.daysWaited >= 1 && sellerProfile !== 'inactive') {
    tips.push('Metti subito il like: molti venditori inviano uno sconto spontaneo ai follower entro 48–72 ore.')
  }
  const precise = targetPrice - 1
  if (targetPrice >= 10 && Number.isInteger(targetPrice) && targetPrice % 5 === 0 && riskBand.id !== 'low'
    && computeDiscountPct(listPrice, precise) <= VINTED.MAX_DISCOUNT_PCT) {
    tips.push(`Un importo preciso (ad esempio ${precise} € invece di ${targetPrice} €) sembra più ragionato e viene contro-rilanciato meno.`)
  }
  if (now.getMonth() === 7 && now.getDate() <= 25) {
    tips.push('Siamo in piena estate: controlla che il venditore non sia in modalità vacanza prima di inviare.')
  }
  return tips
}

// ───────────────────────── src/core/analyze.js ─────────────────────────
/** Below this discount (or euro gap) an offer is pointless: buy at list price. */
const MIN_MEANINGFUL_DISCOUNT_PCT = 0.5
const MIN_MEANINGFUL_GAP_EUR = 0.5

/**
 * Parses a price typed the Italian way: "12,50", "1.200", "1.200,50", "45 €".
 * Returns NaN for anything that is not a plain decimal number.
 */
function parsePrice(raw) {
  if (typeof raw === 'number') return Number.isFinite(raw) ? raw : NaN
  let s = String(raw ?? '').trim().replace(/€/g, '').replace(/\s+/g, '')
  if (!s) return NaN
  if (s.includes('.') && s.includes(',')) {
    // Both separators: the last one is the decimal mark.
    s = s.lastIndexOf(',') > s.lastIndexOf('.') ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '')
  } else if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
    s = s.replace(/\./g, '') // Italian thousands separator
  } else {
    s = s.replace(',', '.')
  }
  if (!/^\d+(\.\d{1,2})?$/.test(s)) return NaN
  return Number(s)
}

/**
 * Validates raw form values. Returns { ok, errors, input } where `input` is the
 * normalised object consumed by the scoring engine.
 */
function normalizeInput(raw) {
  const errors = {}
  const listPrice = parsePrice(raw.listPrice)
  const targetPrice = parsePrice(raw.targetPrice)
  const category = findCategory(raw.category)

  if (!category) errors.category = 'Scegli una categoria.'
  if (!Number.isFinite(listPrice) || listPrice <= 0) errors.listPrice = 'Inserisci il prezzo di listino (maggiore di 0, ad esempio 12,50).'
  if (!Number.isFinite(targetPrice) || targetPrice <= 0) errors.targetPrice = 'Inserisci il prezzo che vorresti pagare (ad esempio 10).'
  if (Object.keys(errors).length) return { ok: false, errors, input: null }

  return { ok: true, errors: {}, input: withPrices({
    itemTitle: (raw.itemTitle || '').trim(),
    category,
    listingAge: findListingAge(raw.listingAge),
    sellerProfile: raw.sellerProfile || 'unknown',
    listingSignal: findListingSignal(raw.listingSignal),
  }, listPrice, targetPrice) }
}

/** Derives discount and risk band from the two prices. */
const withPrices = (input, listPrice, targetPrice) => {
  const discountPct = computeDiscountPct(listPrice, targetPrice)
  return { ...input, listPrice, targetPrice, discountPct, riskBand: riskBandFor(discountPct) }
}

/** Price grid used when searching prices: 0,50 € under 20 €, 1 € under 200 €, then 5 €. */
const priceStepFor = (listPrice) => (listPrice < 20 ? 0.5 : listPrice < 200 ? 1 : 5)

/**
 * Smallest price increase (from the target upward) whose best moment reaches the
 * target overall probability. Probes the top of the range first so that an
 * unreachable target costs one scheduler run, then bisects the price grid.
 */
function suggestPrice(input, now, targetProbability) {
  const step = priceStepFor(input.listPrice)
  const steps = Math.floor((input.listPrice - input.targetPrice) / step) - (Number.isInteger((input.listPrice - input.targetPrice) / step) ? 1 : 0)
  if (steps < 1) return null
  const evaluate = (i) => {
    const candidate = withPrices(input, input.listPrice, Math.round((input.targetPrice + i * step) * 100) / 100)
    const moments = pickMoments(candidate, now)
    return { candidate, moments, ok: moments.chosen.pOverall >= targetProbability }
  }
  let hi = evaluate(steps)
  if (!hi.ok) return null
  let lo = 0 // index 0 is the user's own target, known to be below the target probability
  let hiIndex = steps
  while (hiIndex - lo > 1) {
    const mid = Math.floor((lo + hiIndex) / 2)
    const probe = evaluate(mid)
    if (probe.ok) { hi = probe; hiIndex = mid } else lo = mid
  }
  return {
    price: hi.candidate.targetPrice,
    discountPct: hi.candidate.discountPct,
    probability: hi.moments.chosen.pOverall,
    date: hi.moments.chosen.date,
  }
}

/** Opening/closing prices for a two-step negotiation, only when the opening offer is still credible and sendable. */
function twoStepFor(input, chosen) {
  if (input.riskBand.id !== 'high') return null
  let openingPrice = Math.round(input.targetPrice * 0.94)
  if (openingPrice % 5 === 0) openingPrice -= 1
  if (openingPrice <= 0 || openingPrice >= input.targetPrice) return null
  const probe = withPrices(input, input.listPrice, openingPrice)
  if (probe.discountPct > VINTED.MAX_DISCOUNT_PCT) return null
  const score = scoreAt(probe, chosen.date, chosen.daysWaited)
  if (score.pAccept < 0.2) return null
  if (blockRiskAt(probe, chosen.date).level === 'high') return null
  return { openingPrice, closingPrice: input.targetPrice, openingProbability: score.pAccept, openingDiscountPct: probe.discountPct }
}

function buildWarnings(now) {
  const warnings = []
  if (deviceOffsetMinutes(now) !== romeOffsetMinutes(now)) {
    warnings.push({ id: 'timezone', text: 'Il tuo orologio non è sull\'ora italiana: le fasce orarie sono pensate per venditori in Italia, ricalcola gli orari di conseguenza.' })
  }
  return warnings
}

const noOfferNeeded = (input, now, message) => ({ ok: true, kind: 'no_offer_needed', input, now, message })

function buildAnalysis(input, now, options = {}) {
  const moments = pickMoments(input, now, options)
  const { chosen, nowSlot, sendNow } = moments
  const attribution = attributeFactors(chosen.score)
  const blockRisk = blockRiskAt(input, chosen.date)
  const blockRiskNow = blockRiskAt(input, nowSlot.date)
  const uncertainty = uncertaintyFor(input)
  const verdict = buildVerdict(chosen, sendNow, now, moments.best)
  const twoStep = twoStepFor(input, chosen)
  // The read probability is the one factor a higher price cannot change, so the price target is scaled by it.
  const targetProbability = (blockRisk.level === 'high' ? SUGGESTED_PRICE_TARGET_HIGH_BLOCK : SUGGESTED_PRICE_TARGET) * readProbability(input)
  const suggestedPrice = chosen.pOverall < targetProbability ? suggestPrice(input, now, targetProbability) : null
  const ambition = moments.maxAccept < 0.15 ? 'unrealistic' : moments.maxAccept < 0.3 ? 'ambitious' : null
  const messageBeforeOffer = blockRisk.level === 'high' || input.sellerProfile === 'inactive'

  return {
    ok: true,
    kind: 'analysis',
    input,
    now,
    probability: chosen.pOverall,
    probabilityRange: [Math.max(0.01, chosen.pOverall - uncertainty), Math.min(0.99, chosen.pOverall + uncertainty)],
    uncertainty,
    components: { pAccept: chosen.score.pAccept, pAvailable: chosen.pAvailable, pRead: chosen.pRead },
    riskBand: input.riskBand,
    ambition,
    negligibleDiscount: input.discountPct < NEGLIGIBLE_DISCOUNT_PCT,
    blockRisk,
    blockRiskNow,
    optimal: chosen,
    best: moments.best,
    alsoGood: moments.alsoGood,
    quick: moments.quick,
    alternatives: moments.alternatives,
    nowSlot,
    sendNow,
    pinned: moments.pinned,
    timingMatters: moments.timingMatters,
    timingNote: buildTimingNote(moments, chosen),
    spread: moments.spread,
    horizon: moments.horizon,
    verdict,
    opening: openingSentence(input, moments.timingMatters),
    reasons: buildReasons(input, chosen, attribution),
    factors: attribution,
    tips: buildTips({ input, blockRisk, twoStep, chosen, now, messageBeforeOffer }),
    suggestedPrice,
    twoStep,
    messageBeforeOffer,
    messages: buildMessages({ ...input, sendAt: chosen.date, beforeOffer: messageBeforeOffer }),
    recommendedTone: recommendedToneFor(input),
    avoid: avoidWindows(),
    avoidToday: avoidWindowsOn(chosen.date),
    nowInAvoid: nowSlot.score.timeWindow.weight < 0,
    warnings: buildWarnings(now),
  }
}

/**
 * Entry point: raw form values + current date → full analysis for the UI.
 * kinds: 'analysis' | 'no_offer_needed' | 'over_cap' (discount above Vinted's 40% limit).
 */
function analyzeOffer(raw, now = new Date(), options = {}) {
  const normalized = normalizeInput(raw)
  if (!normalized.ok) return { ok: false, errors: normalized.errors }
  // The learned profile rides on the input, so every scoreAt call (slots, price search, two-step) sees it.
  const input = options.profile ? { ...normalized.input, profile: options.profile } : normalized.input

  if (input.discountPct <= 0) {
    return noOfferNeeded(input, now, 'Il prezzo che vorresti pagare è pari o superiore al prezzo di listino: compra direttamente, non serve nessuna offerta.')
  }
  if (input.discountPct < MIN_MEANINGFUL_DISCOUNT_PCT || input.listPrice - input.targetPrice < MIN_MEANINGFUL_GAP_EUR) {
    return noOfferNeeded(input, now, `Lo sconto richiesto è simbolico (${formatEuro(input.listPrice - input.targetPrice)}): compra a prezzo pieno o chiedi la spedizione inclusa, un'offerta non ha senso.`)
  }

  if (input.discountPct > VINTED.MAX_DISCOUNT_PCT) {
    const cappedPrice = Math.ceil(input.listPrice * (1 - VINTED.MAX_DISCOUNT_PCT / 100) * 100) / 100
    if (input.listPrice - cappedPrice < MIN_MEANINGFUL_GAP_EUR) {
      return noOfferNeeded(input, now, 'Su un prezzo così basso non esiste un\'offerta inviabile: compra direttamente.')
    }
    const capped = withPrices(input, input.listPrice, cappedPrice)
    return {
      ...buildAnalysis(capped, now, options),
      kind: 'over_cap',
      requestedInput: input,
      cappedPrice,
      message: `Vinted non accetta offerte sotto il ${100 - VINTED.MAX_DISCOUNT_PCT}% del prezzo: il minimo inviabile è ${formatEuro(cappedPrice)}. L'analisi qui sotto vale per quella cifra.`,
      capAdvice: [
        'Metti il like e aspetta: lo sconto proposto dal venditore non ha il limite del 40%.',
        'Scrivi un messaggio cordiale spiegando il tuo budget, senza criticare l\'articolo.',
        `Oppure alza il tuo target almeno a ${formatEuro(cappedPrice)} e invia l'offerta nel momento consigliato.`,
      ],
    }
  }

  return buildAnalysis(input, now, options)
}

// ───────────────────────── src/core/optimize.js ─────────────────────────
/** Next "round" goal above the current probability: 63% → 70%, 88% → 93%, capped at 95%. */
const nextGoalFor = (p) => {
  if (p >= 0.9) return 0.95
  return Math.min(0.9, Math.ceil((p + 0.03) * 10) / 10)
}

const GOAL_CHOICES = [0.5, 0.6, 0.7, 0.8, 0.9]

const roundPrice = (v) => Math.round(v * 100) / 100

const bestByProbability = (moments) =>
  [...moments.eligible].sort((a, b) => b.pOverall - a.pOverall || a.date - b.date)[0]

/** Smallest grid index i in [1, n] whose predicate holds (predicate is monotone in i), or null. */
function bisect(n, predicate) {
  if (n < 1 || !predicate(n)) return null
  let lo = 0
  let hi = n
  while (hi - lo > 1) {
    const mid = Math.floor((lo + hi) / 2)
    if (predicate(mid)) hi = mid
    else lo = mid
  }
  return hi
}

const describeSlot = (slot, now) =>
  slot.kind === 'now' ? 'adesso' : `${formatLongDate(slot.date, now)} alle ${formatTime(slot.date)} (${formatRelativeDay(slot.date, now)})`

/**
 * Finds the cheapest ways to reach a target overall probability: waiting for a
 * better moment, raising the offer, or both. Every option carries what to apply
 * (`targetPrice`, `preferredSendAt`) so the UI can re-run the analysis with it.
 */
function optimizeOffer(raw, now = new Date(), { targetProbability = null, profile = null } = {}) {
  const normalized = normalizeInput(raw)
  if (!normalized.ok) return { ok: false, errors: normalized.errors }
  let input = profile ? { ...normalized.input, profile } : normalized.input
  if (input.discountPct <= 0) return { ok: false, reason: 'no_offer_needed' }
  let capped = false
  if (input.discountPct > VINTED.MAX_DISCOUNT_PCT) {
    input = withPrices(input, input.listPrice, Math.ceil(input.listPrice * (1 - VINTED.MAX_DISCOUNT_PCT / 100) * 100) / 100)
    capped = true
  }

  const current = pickMoments(input, now)
  const currentP = current.chosen.pOverall
  const target = targetProbability || nextGoalFor(currentP)
  const step = priceStepFor(input.listPrice)
  const gridSize = Math.max(0, Math.ceil((input.listPrice - input.targetPrice) / step) - 1)
  const priceAt = (i) => roundPrice(Math.min(input.listPrice - step, input.targetPrice + i * step))

  const options = []
  const makeOption = (id, label, { price, slot, probability, changes, momentsOf }) => ({
    id,
    label,
    price,
    discountPct: withPrices(input, input.listPrice, price).discountPct,
    slot,
    slotLabel: describeSlot(slot, now),
    probability,
    deltaPoints: Math.round((probability - currentP) * 100),
    priceIncrease: roundPrice(price - input.targetPrice),
    daysWaited: slot.daysWaited,
    changes,
    apply: { targetPrice: price, preferredSendAt: slot.date.toISOString() },
    reachesTarget: probability >= target,
    momentsOf,
  })

  // Lever 1: only wait for the best moment in the horizon.
  const waitSlot = bestByProbability(current)
  if (waitSlot && waitSlot !== current.chosen && waitSlot.pOverall > currentP + 0.005) {
    options.push(makeOption('wait', 'Aspetta il momento migliore', {
      price: input.targetPrice,
      slot: waitSlot,
      probability: waitSlot.pOverall,
      changes: [`Invia ${describeSlot(waitSlot, now)} invece di ${describeSlot(current.chosen, now)}`],
    }))
  }

  // Lever 2: only raise the offer, keeping the recommended moment.
  const chosenSlot = current.chosen
  const pAtPrice = (i) => evaluateSlot(withPrices(input, input.listPrice, priceAt(i)), chosenSlot).pOverall
  const priceIdx = bisect(gridSize, (i) => pAtPrice(i) >= target)
  if (priceIdx !== null) {
    const price = priceAt(priceIdx)
    options.push(makeOption('price', 'Alza un po\' l\'offerta', {
      price,
      slot: chosenSlot,
      probability: pAtPrice(priceIdx),
      changes: [`Offri ${formatEuro(price)} invece di ${formatEuro(input.targetPrice)} (+${formatEuro(roundPrice(price - input.targetPrice))})`],
    }))
  }

  // Lever 3: smallest raise combined with the best moment at that price.
  const momentsCache = new Map()
  const momentsAt = (i) => {
    if (!momentsCache.has(i)) momentsCache.set(i, pickMoments(withPrices(input, input.listPrice, priceAt(i)), now))
    return momentsCache.get(i)
  }
  const comboIdx = bisect(gridSize, (i) => bestByProbability(momentsAt(i)).pOverall >= target)
  if (comboIdx !== null) {
    const m = momentsAt(comboIdx)
    const slot = bestByProbability(m)
    const price = priceAt(comboIdx)
    const duplicate = options.some((o) => Math.abs(o.price - price) < 0.001 && isSameDay(o.slot.date, slot.date) && o.slot.date.getTime() === slot.date.getTime())
    if (!duplicate) {
      options.push(makeOption('combined', 'Alza un po\' e scegli il momento', {
        price,
        slot,
        probability: slot.pOverall,
        changes: [
          `Offri ${formatEuro(price)} invece di ${formatEuro(input.targetPrice)} (+${formatEuro(roundPrice(price - input.targetPrice))})`,
          `Invia ${describeSlot(slot, now)}`,
        ],
      }))
    }
  }

  // Ceiling: the most the model can reach without paying list price.
  const topMoments = gridSize >= 1 ? momentsAt(gridSize) : current
  const topSlot = bestByProbability(topMoments)
  const maxAchievable = makeOption('max', 'Il massimo raggiungibile', {
    price: gridSize >= 1 ? priceAt(gridSize) : input.targetPrice,
    slot: topSlot,
    probability: topSlot.pOverall,
    changes: gridSize >= 1
      ? [`Offri ${formatEuro(priceAt(gridSize))}`, `Invia ${describeSlot(topSlot, now)}`]
      : [`Invia ${describeSlot(topSlot, now)}`],
  })

  const reaching = options.filter((o) => o.reachesTarget)
  // Cheapest first: less money, then fewer days of waiting.
  reaching.sort((a, b) => a.priceIncrease - b.priceIncrease || a.daysWaited - b.daysWaited)
  const partial = options.filter((o) => !o.reachesTarget).sort((a, b) => b.probability - a.probability)

  return {
    ok: true,
    capped,
    target,
    current: { probability: currentP, price: input.targetPrice, slot: current.chosen, slotLabel: describeSlot(current.chosen, now) },
    reachable: reaching.length > 0,
    options: reaching,
    partial,
    maxAchievable,
    recommended: reaching[0] || null,
  }
}

// ───────────────────────── src/core/counter.js ─────────────────────────
/**
 * Counter-offers: our reply when the seller answers our offer with his own price ("Fai il tuo prezzo").
 *
 * For every candidate price c and send moment t the engine computes E(c, t), the euros the buyer is expected to pay
 * in the end, over four outcomes: the seller accepts; he counters again and we follow a shrinking-step rule (one round
 * of lookahead); he declines or goes silent and we fall back to his price or the list price; the item sells to someone
 * else meanwhile (cost: the value of the item). It recommends the (c, t) with the lowest E, or accepting his price
 * when countering would save too little. Acceptance is the eBay field model (Backus et al. 2020) on the share of the
 * remaining gap we concede, plus the split bonus, the seller's stance and the existing time and month windows.
 * Every unknown Vinted rule (counter expiry, survival of his price after our new offer, round limit) is an explicit,
 * configurable assumption: see VINTED_ASSUMED and COUNTER in constants.js.
 *
 * Private helpers are prefixed `ctr` because the artifact bundler puts every module in one scope.
 */

const CTR_EPS = 1e-9
const ctrR2 = (v) => Math.round(v * 100) / 100
const ctrHours = (from, to) => (to.getTime() - from.getTime()) / 3_600_000
const ctrClamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v))
const ctrCeilCent = (x) => Math.ceil(x * 100 - CTR_EPS) / 100
const ctrFloor5 = (d) => new Date(Math.floor(d.getTime() / 300_000) * 300_000)
const ctrPct = (v) => String(Math.round(v * 10) / 10).replace('.', ',')
/** Italian article before a percentage: "il 10%", "l'8%", "l'11%", "l'80%". */
const ctrIl = (n) => {
  const r = Math.round(n)
  if (r === 0) return 'lo '
  return r === 1 || r === 8 || r === 11 || (r >= 80 && r <= 89) ? "l'" : 'il '
}
const ctrApprox = (price, listPrice) => formatEuro(listPrice >= 200 ? Math.round(price) : Math.round(price * 10) / 10)

/* ───────── prices ───────── */

/** "30", "30%", "30,5" → 30 / 30.5. Negative, above 200 or junk → NaN. */
const parsePercent = (raw) => {
  if (typeof raw === 'number') return Number.isFinite(raw) && raw >= 0 && raw <= 200 ? raw : NaN
  const s = String(raw ?? '').trim().replace('%', '').replace(/\s+/g, '').replace(',', '.')
  if (!/^\d+(\.\d+)?$/.test(s)) return NaN
  const v = Number(s)
  return v <= 200 ? v : NaN
}

/** Seller counter typed as "% above my offer": 45 € + 30% = 58,50 €. Rounded to the cent, never to a price grid. */
const counterFromPercent = (previousOffer, pct) => Math.round(previousOffer * (100 + pct)) / 100

const ctrGrid = (listPrice) => (listPrice < 200 ? 0.1 : 1)

/**
 * "Precise" amounts anchor harder than round ones (Mason et al. 2013) without looking odd:
 * under 200 € cents .30 / .70 / .80 or a whole euro that is not a multiple of 5; from 200 € integers not divisible by 5.
 */
const isPrecisePrice = (price, listPrice) => {
  if (listPrice >= 200) {
    const r = Math.round(price)
    return Math.abs(price - r) < 1e-6 && r % 5 !== 0
  }
  const cents = Math.round(price * 100) % 100
  const euros = Math.floor(Math.round(price * 100) / 100)
  return cents === 30 || cents === 70 || cents === 80 || (cents === 0 && euros % 5 !== 0)
}

const precisePricesIn = (lo, hi, listPrice) => {
  const out = []
  const g = ctrGrid(listPrice)
  for (let k = Math.ceil(lo / g - CTR_EPS); k * g <= hi + CTR_EPS; k++) {
    const v = ctrR2(k * g)
    if (isPrecisePrice(v, listPrice)) out.push(v)
  }
  return out
}

/** Largest precise price ≤ x and strictly above `floorExclusive`, or null. */
const preciseBelow = (x, listPrice, floorExclusive = -Infinity) => {
  const g = ctrGrid(listPrice)
  for (let k = Math.floor(x / g + CTR_EPS); k * g > floorExclusive + CTR_EPS; k--) {
    const v = ctrR2(k * g)
    if (isPrecisePrice(v, listPrice)) return v
  }
  return null
}

/** Midpoint, rounded down to the cent (to the euro from 200 €). */
const splitPrice = (a, b, listPrice) => {
  const exact = (a + b) / 2
  return listPrice >= 200 ? Math.round(exact - CTR_EPS) : Math.floor(exact * 100 + CTR_EPS) / 100
}

/** Backus' definition of an exact split: γ = 0,50 ± 0,005 of the gap (at least 1 cent, 0,50 € from 200 €). */
const splitTolerance = (a, b, listPrice) =>
  listPrice >= 200 ? Math.max(COUNTER.SPLIT_TOLERANCE_SHARE * (b - a), 0.5) : Math.max(COUNTER.SPLIT_TOLERANCE_SHARE * (b - a), 0.01)

const isSplitPrice = (price, a, b, listPrice) => Math.abs(price - (a + b) / 2) <= splitTolerance(a, b, listPrice) + CTR_EPS

/** For when Vinted refuses cents: nearest whole euro that is not a multiple of 5, ties to the lower one. */
const wholeEuroFallback = (price) => {
  const options = [Math.floor(price), Math.ceil(price), Math.floor(price) - 1, Math.ceil(price) + 1].filter((v) => v % 5 !== 0)
  return options.sort((a, b) => Math.abs(a - price) - Math.abs(b - price) || a - b)[0]
}

/** What the buyer really pays (item + Vinted fee), shipping excluded. */
const buyerTotal = (price) => ctrR2(price * (1 + VINTED.BUYER_FEE_PCT / 100) + VINTED.BUYER_FEE_FIXED)

/** Stance from the share of the gap the seller conceded (normalised to the first round). */
const sellerStanceOf = (share) => {
  const t = COUNTER.STANCE_THRESHOLDS
  if (share <= t.hold) return 'hold'
  if (share <= t.firm) return 'firm'
  if (share < t.moving) return 'moving'
  return 'flexible'
}

/** Sellers concede less in later rounds (Keniston: 0,42 then 0,23): rescale to the first-round scale. */
/**
 * The seller's concession relative to a typical first-round one. `mult` (learned, default 1) says how much this
 * user's sellers concede compared with eBay's mean: conceding 42% of the gap is "average" only where 42% is average.
 */
const ctrNormShare = (share, roundIdx, mult = 1) => {
  const means = COUNTER.ROUND_MEAN_SHARE
  return Math.min(0.9, (share * (means[0] / means[Math.min(roundIdx, means.length - 1)])) / mult)
}

/* ───────── input ───────── */

const ctrDate = (v) => {
  if (!v) return null
  const d = v instanceof Date ? v : new Date(v)
  return Number.isFinite(d.getTime()) ? d : null
}

const ctrMaxPrice = (raw) => {
  if (raw === undefined || raw === null || raw === '') return null
  const w = parsePrice(raw)
  return Number.isFinite(w) && w > 0 ? w : null
}

/**
 * Validates the raw form (strings, as forms provide them) and derives the negotiation state.
 * Returns { ok, errors, warnings, state }.
 */
function normalizeCounterInput(raw, now = new Date(), options = {}) {
  const errors = {}
  const warnings = []
  const history = Array.isArray(raw.history) && raw.history.length
    ? raw.history.map((h) => ({ by: h.by, price: Number(h.price), at: ctrDate(h.at), isFinal: Boolean(h.isFinal), unc: Number(h.unc ?? h.receivedUncertaintyMinutes) || 0 }))
    : null
  let useHistory = false
  if (history) {
    useHistory = history.length >= 2 && history[0].by === 'buyer' && history[history.length - 1].by === 'seller'
      && history.every((h, i) => h.by === (i % 2 === 0 ? 'buyer' : 'seller') && Number.isFinite(h.price) && h.price > 0)
    if (!useHistory) errors.history = "La trattativa salvata non è valida: l'ultima mossa deve essere una controproposta del venditore."
  }
  const buyerEntries = useHistory ? history.filter((h) => h.by === 'buyer') : null
  const sellerEntries = useHistory ? history.filter((h) => h.by === 'seller') : null
  const previousRaw = useHistory
    ? buyerEntries[buyerEntries.length - 1].price
    : (raw.previousOffer !== undefined && raw.previousOffer !== null && raw.previousOffer !== '' ? raw.previousOffer : raw.targetPrice)

  const base = normalizeInput({ ...raw, targetPrice: previousRaw })
  if (!base.ok) {
    if (base.errors.category) errors.category = base.errors.category
    if (base.errors.listPrice) errors.listPrice = base.errors.listPrice
    if (base.errors.targetPrice) errors.previousOffer = "Inserisci l'offerta che hai inviato (ad esempio 45)."
  }

  const mode = raw.counterMode === 'pct' ? 'pct' : 'eur'
  const B0 = parsePrice(previousRaw)
  let S0 = NaN
  let enteredAs = null
  if (!history) {
    if (mode === 'pct') {
      const pct = parsePercent(raw.sellerCounter)
      if (Number.isFinite(pct) && Number.isFinite(B0)) S0 = counterFromPercent(B0, pct)
      enteredAs = { mode, value: pct }
    } else {
      S0 = parsePrice(raw.sellerCounter)
      enteredAs = { mode, value: S0 }
    }
    if (!Number.isFinite(S0) || S0 <= 0) errors.sellerCounter = 'Inserisci la controproposta del venditore (ad esempio 58,50 o 30%).'
  }
  if (Object.keys(errors).length) return { ok: false, errors, warnings, state: null }

  const input = options.profile ? { ...base.input, profile: options.profile } : base.input
  const L = input.listPrice
  const buyers = useHistory ? buyerEntries.map((h) => h.price) : [B0]
  const sellers = useHistory ? sellerEntries.map((h) => h.price) : [S0]
  const lastSeller = sellers[sellers.length - 1]
  if (lastSeller > L + CTR_EPS) {
    let message = 'La controproposta non può superare il prezzo di listino.'
    if (!useHistory && mode === 'pct') message = `La controproposta non può superare il prezzo di listino (${formatEuro(B0)} + ${ctrPct(enteredAs.value)}% = ${formatEuro(S0)}).`
    return { ok: false, errors: { sellerCounter: message }, warnings, state: null }
  }

  const k = sellers.length
  const n = buyers.length - 1
  const B = buyers[n]
  const Sprev = k >= 2 ? sellers[k - 2] : L
  const raised = lastSeller > Sprev + 0.009
  const S = raised ? Sprev : lastSeller
  if (raised) warnings.push({ id: 'seller_raised', text: `Ha alzato il prezzo rispetto alla sua proposta precedente: non inseguirlo, ragioniamo sui ${formatEuro(Sprev)}.` })
  const sigma = ctrR2(Sprev - S)
  const denominator = Sprev - B
  const share = denominator > CTR_EPS ? Math.max(0, sigma) / denominator : 1
  const shareNorm = ctrNormShare(share, k - 1, counterShareOf(options.profile))
  const stance = sellerStanceOf(shareNorm)

  // Times: history wins (saved items), then an explicit date, then the "quando l'hai ricevuta?" chip.
  let receivedAt = useHistory ? sellerEntries[k - 1].at : null
  let unc = receivedAt ? sellerEntries[k - 1].unc : 0
  if (!receivedAt) receivedAt = ctrDate(raw.receivedAt)
  if (!receivedAt) {
    const chip = COUNTER_RECEIVED_AGO.find((c) => c.id === raw.receivedAgo) || COUNTER_RECEIVED_AGO[0]
    receivedAt = addMinutes(now, -chip.minutes)
    unc = chip.halfWidth
  }
  if (receivedAt.getTime() > now.getTime()) receivedAt = new Date(now)
  const offerSentAt = (useHistory ? buyerEntries[n].at : null) || ctrDate(raw.offerSentAt)
  const latencyH = offerSentAt ? Math.max(5 / 60, ctrHours(offerSentAt, receivedAt)) : null

  const inactive = input.sellerProfile === 'inactive'
  const profile = inactive ? 'unknown' : input.sellerProfile
  const ageDays = input.listingAge.days + (offerSentAt ? Math.max(0, calendarDaysBetween(offerSentAt, now)) : 0)
  const hazard = input.category.dailySellRate * ageHazardMultiplier(ageDays)
    * (raw.competition ? COUNTER.COMPETITION_MULT : 1) * (raw.publicPrice ? COUNTER.PUBLIC_PRICE_MULT : 1)
  const W = ctrMaxPrice(raw.maxPrice)
  const Wcap = W ?? Infinity
  const V = ctrR2(Math.max(L * (1 + COUNTER.LOSS_PREMIUM), W ?? 0))
  const chat = raw.channel === 'chat'
  const theta = Boolean(raw.publicPrice) || chat
  const validityHours = options.validityHours === undefined ? VINTED_ASSUMED.COUNTER_VALIDITY_HOURS : options.validityHours
  const assumedExpiry = chat || validityHours == null ? null : addMinutes(receivedAt, validityHours * 60 - unc)
  const deadline = assumedExpiry ? addMinutes(assumedExpiry, -COUNTER.DEADLINE_MARGIN_MINUTES) : null
  const planHorizon = addMinutes(receivedAt, COUNTER.PLAN_HORIZON_HOURS * 60)
  const minDelayMinutes = inactive ? COUNTER.MIN_DELAY_INACTIVE_MINUTES : COUNTER.MIN_DELAY_MINUTES
  const tMin = ceilToMinutes(new Date(Math.max(addMinutes(now, 5).getTime(), addMinutes(receivedAt, minDelayMinutes).getTime())), 5)
  const goalPrice = raw.goalPrice === undefined || raw.goalPrice === null || raw.goalPrice === '' ? null : parsePrice(raw.goalPrice)

  if (B < L * (1 - VINTED.MAX_DISCOUNT_PCT / 100) - CTR_EPS) {
    warnings.push({ id: 'below_floor', text: 'Di solito Vinted non accetta offerte sotto il 60% del prezzo: controlla i numeri.' })
  }
  if (Number(raw.offersSentToday) >= COUNTER.DAILY_QUOTA_WARN) {
    warnings.push({ id: 'daily_quota', text: `Ti restano poche offerte oggi: Vinted ne consente ${VINTED.OFFERS_PER_DAY} al giorno.` })
  }
  warnings.push(...buildWarnings(now))

  const state = {
    raw, input, now, L, B, S, S0: S, raised, lastSeller, lastBuyerFinal: Boolean(useHistory && n >= 1 && buyerEntries[n].isFinal),
    expired: Boolean(assumedExpiry && assumedExpiry.getTime() <= now.getTime()),
    Sprev, sigma, share, shareNorm, stance, k, n, buyers, sellers, mode, enteredAs,
    receivedAt, unc, offerSentAt, latencyH, inactive, profile, ageDays, hazard, W, Wcap, V, chat, theta, validityHours,
    assumedExpiry, deadline, planHorizon, minDelayMinutes, tMin, minStep: priceStepFor(L), goalPrice: Number.isFinite(goalPrice) ? goalPrice : null,
    cache: new Map(),
  }
  return { ok: true, errors: {}, warnings, state }
}

/**
 * The line under the "controproposta" field while the user types: what the seller's number means.
 * Returns null until list price, previous offer and counter are all valid.
 */
function counterPreview(raw) {
  const L = parsePrice(raw.listPrice)
  const B = parsePrice(raw.previousOffer !== undefined && raw.previousOffer !== '' ? raw.previousOffer : raw.targetPrice)
  if (!(L > 0) || !(B > 0)) return null
  const S = raw.counterMode === 'pct' ? counterFromPercent(B, parsePercent(raw.sellerCounter)) : parsePrice(raw.sellerCounter)
  if (!(S > 0)) return null
  if (S > L + CTR_EPS) return { S, overList: true, text: `${formatEuro(S)} supera il prezzo di listino (${formatEuro(L)}): controlla la cifra.` }
  if (S <= B + CTR_EPS) return { S, atOrBelowOffer: true, text: `${formatEuro(S)} è pari o sotto la tua offerta: puoi comprare subito.` }
  // Later rounds: the step is measured from his previous counter, not from the list price.
  const prev = Number(raw.sellerPrevious) > 0 ? Math.min(Number(raw.sellerPrevious), L) : L
  const from = prev < L - CTR_EPS ? 'dalla sua proposta precedente' : 'dal listino'
  const overPct = (S / B - 1) * 100
  const sigma = ctrR2(prev - S)
  const share = prev - B > CTR_EPS ? Math.max(0, sigma) / (prev - B) : 1
  const stance = sellerStanceOf(share)
  const moved = sigma > 0.009
    ? `è sceso di ${formatEuro(sigma)} ${from} (−${ctrPct((sigma / prev) * 100)}%), ${ctrIl(share * 100)}${Math.round(share * 100)}% della distanza`
    : sigma < -0.009 ? `ha alzato la cifra rispetto alla sua proposta precedente (${formatEuro(prev)})` : `non è sceso ${from}`
  const over = overPct < 0.5 ? 'appena sopra la tua offerta' : `${ctrIl(overPct)}${Math.round(overPct)}% sopra la tua offerta`
  return { S, overPct, sigma, share, stance, text: `${formatEuro(S)} · ${over} · ${moved}` }
}

/* ───────── acceptance model ───────── */

const ctrSellerLabel = (id) => ({ new_seller: 'Venditore nuovo', expert: 'Venditore esperto' })[id] || 'Venditore non indicato'

/**
 * Probability that the seller accepts our price against his price S (B = our last rejected offer, shareNorm = how much
 * he moved). `sendDate` = the real moment we send it, or null for the lookahead (our next counter).
 * The returned score has the shape attributeFactors() expects (base, pBase, pAccept, factors).
 */
function counterAcceptance(state, side, price, sendDate = null) {
  const { B, S, shareNorm } = side
  const { input } = state
  const D = COUNTER.PRIOR_DAMPING
  const gapShare = (price - B) / (S - B)
  const core = COUNTER.CORE_INTERCEPT + COUNTER.CORE_SLOPE * (gapShare - 0.5)
  const isSplit = isSplitPrice(price, B, S, state.L)
  const split = isSplit ? COUNTER.SPLIT_BONUS * ramp(B / S, COUNTER.SPLIT_RATIO_RAMP[0], COUNTER.SPLIT_RATIO_RAMP[1]) : 0
  const ageToday = input.listingAge.id === 'unknown' ? 0 : ageCurve(state.ageDays) * input.category.ageMultiplier
  const mods = [
    { id: 'counter_stance', group: 'counter_stance', label: 'Quanto è sceso il venditore', weight: interpolate(COUNTER.STANCE_CURVE, shareNorm) },
    { id: 'category', group: 'category', label: `Categoria ${input.category.label.toLowerCase()}`, weight: D * input.category.weight },
    { id: 'signal', group: 'signal', label: input.listingSignal.id === 'none' ? 'Testo annuncio' : `Annuncio: ${input.listingSignal.label.toLowerCase()}`, weight: D * input.listingSignal.weight },
    { id: 'age', group: 'age', label: input.listingAge.id === 'unknown' ? 'Anzianità non indicata' : `Annuncio ${input.listingAge.label.toLowerCase()}`, weight: D * ageToday },
    { id: 'seller', group: 'seller', label: ctrSellerLabel(state.profile), weight: D * sellerWeight(state.profile, ((S - price) / S) * 100) },
  ]
  let hoursAfter = null
  let timeWindow = null
  let monthWindow
  if (sendDate) {
    hoursAfter = ctrHours(state.receivedAt, sendDate)
    timeWindow = timeWindowAt(sendDate)
    monthWindow = monthWindowAt(sendDate)
    const diff = Math.abs(minutesOfDay(sendDate) - minutesOfDay(state.receivedAt))
    const circular = Math.min(diff, 1440 - diff)
    const habit = hoursAfter >= COUNTER.HABIT_MIN_DELAY_HOURS && circular <= COUNTER.HABIT_TOLERANCE_MINUTES && state.unc <= COUNTER.HABIT_MAX_UNCERTAINTY_MINUTES
    mods.push(
      { id: 'time', group: 'time', label: timeWindow.label, weight: timeWeight(timeWindow, state.profile), window: timeWindow },
      { id: 'month', group: 'month', label: monthWindow.label, weight: monthWindow.weight, window: monthWindow },
      { id: 'counter_delay', group: 'counter_delay', label: 'Attesa prima di rispondere', weight: COUNTER.DELAY_PER_DOUBLING * Math.log2(ctrClamp(hoursAfter, COUNTER.DELAY_MIN_HOURS, COUNTER.DELAY_MAX_HOURS) / COUNTER.DELAY_REF_HOURS) },
      { id: 'counter_cooling', group: 'counter_cooling', label: 'La sua proposta invecchia', weight: COUNTER.COOLING * ramp(hoursAfter, COUNTER.COOLING_FROM_HOURS, COUNTER.COOLING_TO_HOURS) },
      { id: 'counter_habit', group: 'counter_habit', label: "All'ora in cui era sull'app", weight: habit ? COUNTER.HABIT : 0 },
      { id: 'counter_latency', group: 'counter_latency', label: 'Velocità della sua risposta', weight: state.latencyH == null ? 0 : ctrClamp(COUNTER.LATENCY_COEF * Math.log(state.latencyH / COUNTER.LATENCY_REF_HOURS), COUNTER.LATENCY_MIN, COUNTER.LATENCY_MAX) },
      { id: 'counter_message', group: 'counter_message', label: 'Messaggio con motivo e pagamento subito', weight: COUNTER.MESSAGE_BONUS },
      { id: 'counter_late', group: 'counter_late', label: 'Oltre le 24 ore', weight: state.assumedExpiry && sendDate > state.assumedExpiry ? COUNTER.LATE_PENALTY : 0 },
    )
  } else {
    monthWindow = monthWindowAt(state.now)
    mods.push(
      { id: 'time', group: 'time', label: 'Una buona fascia serale', weight: COUNTER.NEXT_ROUND_WINDOW },
      { id: 'month', group: 'month', label: monthWindow.label, weight: monthWindow.weight, window: monthWindow },
      { id: 'counter_message', group: 'counter_message', label: 'Messaggio con motivo e pagamento subito', weight: COUNTER.MESSAGE_BONUS },
    )
  }
  // Same caps as scoreAt: stacked modifiers stay plausible.
  const sumPos = mods.filter((m) => m.weight > 0).reduce((s, m) => s + m.weight, 0)
  const sumNeg = mods.filter((m) => m.weight < 0).reduce((s, m) => s + m.weight, 0)
  const posScale = sumPos > POSITIVE_CAP ? POSITIVE_CAP / sumPos : 1
  const negScale = sumNeg < NEGATIVE_CAP ? NEGATIVE_CAP / sumNeg : 1
  const capped = mods.map((m) => ({ ...m, rawWeight: m.weight, weight: m.weight > 0 ? m.weight * posScale : m.weight * negScale }))
  const factors = [{ id: 'split', group: 'split', label: 'Metà strada esatta', weight: split }, ...capped]
  const rawLogit = core + factors.reduce((s, f) => s + f.weight, 0)
  // Learned from this user's counters (monthly profile), after the caps like the first-offer correction.
  const learned = learnedCounterRow(input.profile, { windowId: timeWindow ? timeWindow.id : null })
  if (learned) factors.push(learned)
  const logit = learned ? rawLogit + learned.weight : rawLogit
  return {
    gapShare, core, isSplit, split, base: core, pBase: squash(core), logit, rawLogit, learnedWeight: learned ? learned.weight : 0, pAccept: squash(logit), factors,
    capped: posScale < 1 || negScale < 1, timeWindow, monthWindow, hoursAfter,
  }
}

/* ───────── what happens if he does not accept ───────── */

const ctrAvailability = (state, hours) => Math.pow(1 - state.hazard, Math.max(0, hours) / 24)
/** Pressing «Acquista» at x, or (over budget) losing the item. */
const ctrAccCost = (state, x) => (x <= state.Wcap + CTR_EPS ? x : state.V)
const ctrIsBelow = (state, x) => (x <= state.Wcap + CTR_EPS && x < state.S0 - 0.009 ? 1 : 0)
/** After a decline or silence: his price may survive (θ) or we re-offer it (φ), otherwise list price or walk away. */
const ctrFallback = (state, x) => (state.theta
  ? ctrAccCost(state, x)
  : COUNTER.RECOVER_PROB * ctrAccCost(state, x) + (1 - COUNTER.RECOVER_PROB) * (state.L <= state.Wcap + CTR_EPS ? state.L : state.V))
const ctrMinGap = (listPrice) => Math.max(0.5, ctrGrid(listPrice))

/**
 * Our counter number n+1 after the seller answered our last offer `cPrev` with S (deterministic, shrinking steps):
 * a final offer after a hold or on the third counter, the split when it is close, else a step ≤ 0,75× our last one.
 */
function nextCounterMove(state, { cPrev, bPrev, S, Sprev, n }) {
  if (n >= COUNTER.MAX_BUYER_COUNTERS) return null
  const delta = cPrev - bPrev
  const G = S - cPrev
  const sigma = ctrR2(Sprev - S)
  const hi = Math.min(S - ctrMinGap(state.L), state.Wcap)
  if (hi <= cPrev + CTR_EPS) return null
  let price
  let isSplit = false
  let isFinal = false
  if (sigma <= 0.009 || n >= COUNTER.MAX_BUYER_COUNTERS - 1) {
    isFinal = true
    price = preciseBelow(Math.min(cPrev + COUNTER.FINAL_STEP * delta, hi), state.L, cPrev)
  } else if (G / 2 <= COUNTER.SHRINK_MAX * delta + CTR_EPS) {
    price = splitPrice(cPrev, S, state.L)
    isSplit = true
    if (price > hi) {
      price = preciseBelow(hi, state.L, cPrev)
      isSplit = false
    }
  } else {
    const step = ctrClamp(Math.max(COUNTER.SHRINK_MIN * delta, Math.min(sigma, G / 2)), state.minStep, COUNTER.SHRINK_MAX * delta)
    price = preciseBelow(Math.min(cPrev + step, hi), state.L, cPrev)
  }
  if (price == null || price - cPrev < 0.5 * state.minStep - CTR_EPS) return null
  return { price, isSplit, isFinal, step: ctrR2(price - cPrev) }
}

/** Cost and P(paying less than his price) if the seller does NOT accept our counter `price` sent from state `st`. */
function ctrAfterNoAccept(state, st, price, gapShare, isFinal, depthLeft) {
  const eager = ramp(gapShare, COUNTER.EAGER_RAMP[0], COUNTER.EAGER_RAMP[1])
  const counters = COUNTER.COUNTER_SHARE[st.stance]
  const hold = Math.min(COUNTER.HOLD_PROB_MAX, COUNTER.HOLD_PROB[st.stance] + COUNTER.EAGER_HOLD * eager)
  const move = COUNTER.MOVE_SHARE[st.stance] * (1 - COUNTER.EAGER_MOVE * eager)
  let S2 = ctrR2(price + (st.S - price) * (1 - move) * (isPrecisePrice(price, state.L) ? 1 - COUNTER.PRECISION_PULL : 1))
  S2 = Math.min(st.S, Math.max(S2, ctrR2(price + ctrMinGap(state.L))))
  const fallback = ctrFallback(state, st.S)
  let vHold
  let vMove
  if (isFinal || depthLeft <= 0) {
    vHold = { action: 'accept', cost: ctrAccCost(state, st.S), below: ctrIsBelow(state, st.S), price: st.S, sellerPrice: st.S }
    vMove = { action: 'accept', cost: ctrAccCost(state, S2), below: ctrIsBelow(state, S2), price: S2, sellerPrice: S2 }
  } else {
    const next = { cPrev: price, bPrev: st.B, Sprev: st.S, n: st.n + 1, roundIdx: st.roundIdx + 1 }
    vHold = ctrNode(state, { ...next, S: st.S }, depthLeft - 1)
    vMove = ctrNode(state, { ...next, S: S2 }, depthLeft - 1)
  }
  const cost = counters * (hold * vHold.cost + (1 - hold) * vMove.cost) + (1 - counters) * fallback
  const below = counters * (hold * vHold.below + (1 - hold) * vMove.below)
  return { cost, below, counters, hold, move, S2, vHold, vMove, fallback }
}

/** Lookahead node: the seller has just answered our cPrev with S → min(accept S, our deterministic next move). */
function ctrNode(state, st, depthLeft) {
  const accept = { action: 'accept', cost: ctrAccCost(state, st.S), below: ctrIsBelow(state, st.S), price: st.S, sellerPrice: st.S }
  const move = nextCounterMove(state, st)
  if (!move) return accept
  const share = st.Sprev - st.cPrev > CTR_EPS ? Math.max(0, st.Sprev - st.S) / (st.Sprev - st.cPrev) : 1
  const shareNorm = ctrNormShare(share, st.roundIdx, counterShareOf(state.input.profile))
  const stance = sellerStanceOf(shareNorm)
  const score = counterAcceptance(state, { B: st.cPrev, S: st.S, shareNorm }, move.price, null)
  const A = ctrAvailability(state, 24)
  const after = ctrAfterNoAccept(state, { B: st.cPrev, S: st.S, stance, n: st.n, roundIdx: st.roundIdx }, move.price, score.gapShare, move.isFinal, depthLeft)
  const cost = A * (score.pAccept * move.price + (1 - score.pAccept) * after.cost) + (1 - A) * state.V
  const below = A * (score.pAccept + (1 - score.pAccept) * after.below)
  const counter = { action: 'counter', cost, below, price: move.price, isSplit: move.isSplit, isFinal: move.isFinal, pAccept: score.pAccept, sellerPrice: st.S }
  return counter.cost < accept.cost - CTR_EPS ? counter : { ...accept, wouldCounter: counter }
}

/** Full evaluation of our counter `price` sent at `sendDate` from the current state (one round of lookahead). */
function evaluateCounter(state, price, sendDate, { isFinal = false, depth = 1 } = {}) {
  const score = counterAcceptance(state, { B: state.B, S: state.S, shareNorm: state.shareNorm }, price, sendDate)
  const pRead = state.inactive ? COUNTER.INACTIVE_READ_FLOOR + (1 - COUNTER.INACTIVE_READ_FLOOR) * Math.exp(-score.hoursAfter / COUNTER.INACTIVE_READ_TAU_HOURS) : 1
  const pAccept = score.pAccept * pRead
  const pAvailable = ctrAvailability(state, ctrHours(state.now, sendDate) + sellerReplyHoursOf(state.input.profile))
  // The continuation does not depend on the send moment (the lookahead uses a typical window): memoise per price.
  if (!state.cache) state.cache = new Map()
  const key = `${price}|${isFinal ? 1 : 0}|${depth}`
  let after = state.cache.get(key)
  if (!after) {
    after = ctrAfterNoAccept(state, { B: state.B, S: state.S, stance: state.stance, n: state.n, roundIdx: state.k - 1 }, price, score.gapShare, isFinal, depth)
    state.cache.set(key, after)
  }
  const expectedPrice = pAvailable * (pAccept * price + (1 - pAccept) * after.cost) + (1 - pAvailable) * state.V
  const pBelowSeller = pAvailable * (pAccept + (1 - pAccept) * after.below)
  return { price, sendDate, score, pRead, pAccept, pAvailable, after, expectedPrice, pBelowSeller, isFinal }
}

/* ───────── candidate moments ───────── */

const ctrQuiet = (date) => {
  const m = minutesOfDay(date)
  return (m >= COUNTER.QUIET_FROM_MINUTES || m < COUNTER.QUIET_TO_MINUTES) && timeWindowAt(date).weight <= 0
}

/**
 * Moments worth considering: the earliest polite moment (≥ 60 min after his counter), the start and end of every
 * positive window, the canonical evening slots, his habitual minute, an 18:05 bridge, and the soft deadline, for
 * today and the next two days, within 30 h of his counter (72 h from now once it is stale); no quiet hours.
 */
function buildCounterSlots(state, { stale = false, from = null, until = null } = {}) {
  const now = state.now
  const start = from || state.tMin
  const raw = [{ date: start, kind: from ? 'canonical' : start.getTime() - now.getTime() <= 10 * 60_000 ? 'now' : 'min_delay' }]
  const day0 = startOfDay(from || now)
  for (let d = 0; d <= 2; d++) {
    const day = addDays(day0, d)
    const weekday = effectiveWeekday(day)
    for (const w of TIME_WINDOWS.filter((x) => x.weight > 0 && x.days.includes(weekday))) {
      raw.push({ date: atTime(day, 0, w.from + 5), kind: 'window_start' }, { date: atTime(day, 0, w.to - 10), kind: 'window_end' })
    }
    for (const [hh, mm] of CANONICAL_SLOTS[weekday] || []) raw.push({ date: atTime(day, hh, mm), kind: 'canonical' })
    raw.push({ date: atTime(day, 0, Math.floor(minutesOfDay(state.receivedAt) / 5) * 5), kind: 'habit' })
    raw.push({ date: atTime(day, 18, 5), kind: 'bridge' })
  }
  if (state.deadline && !from) raw.push({ date: ctrFloor5(state.deadline), kind: 'deadline' })
  if (state.assumedExpiry && !from) raw.push({ date: ctrFloor5(addMinutes(state.assumedExpiry, -5)), kind: 'expiry' })
  const end = until || (stale ? addMinutes(now, COUNTER.STALE_PLAN_HOURS * 60) : state.planHorizon)
  const seen = new Set()
  const slots = []
  for (const s of raw.sort((a, b) => a.date - b.date || (a.kind === 'now' ? -1 : 0))) {
    const t = s.date.getTime()
    if (t < start.getTime() || t > end.getTime() || seen.has(t) || ctrQuiet(s.date)) continue
    seen.add(t)
    const tier = !state.assumedExpiry || stale || from ? 'on_time' : t <= state.deadline.getTime() ? 'on_time' : t <= state.assumedExpiry.getTime() ? 'tight' : 'late'
    slots.push({ ...s, tier, daysWaited: calendarDaysBetween(now, s.date), windowId: timeWindowAt(s.date).id })
  }
  return slots
}

/* ───────── candidate prices ───────── */

/** First counter: precise prices between a reciprocity floor and the midpoint (or only the split when the gap is tiny). */
function ctrFirstCandidates(state) {
  const { B, S, L } = state
  const G = S - B
  const split = splitPrice(B, S, L)
  const floor60 = ctrCeilCent(L * (1 - VINTED.MAX_DISCOUNT_PCT / 100))
  if (G <= Math.max(COUNTER.CLOSE_GAP_EUR, (COUNTER.CLOSE_GAP_PCT / 100) * L) + CTR_EPS) {
    return { mode: 'close', list: split <= state.Wcap + CTR_EPS ? [split] : [], split, lo: split, hi: split }
  }
  const lo = Math.max(B + Math.max(state.minStep, Math.min(state.sigma, COUNTER.RECIPROCITY_GAP_SHARE * G), COUNTER.MIN_FIRST_SHARE * G), floor60)
  const hi = Math.min(split, S - ctrMinGap(L), state.Wcap, state.stance === 'hold' ? B + COUNTER.HOLD_MAX_SHARE * G : Infinity)
  let list = precisePricesIn(lo, hi, L)
  if (split >= lo - CTR_EPS && split <= hi + CTR_EPS && !list.includes(split)) list.push(split)
  list.sort((a, b) => a - b)
  let mode = 'normal'
  if (!list.length && state.Wcap < lo && state.Wcap > B + state.minStep) {
    const c = preciseBelow(state.Wcap, L, B)
    if (c) {
      list = [c]
      mode = 'budget_final'
    }
  }
  return { mode, list, split, lo, hi }
}

/* ───────── prose ───────── */

const ctrDisclaimer = 'Quanto dura la sua proposta, quanti rilanci sono possibili e cosa succede alla sua cifra quando ne proponi una nuova non sono regole ufficiali di Vinted: il piano usa stime prudenti. Le probabilità vengono da studi su milioni di trattative online, adattate a Vinted.'
const ctrFavouriteTip = "Metti il cuore all'articolo: se abbassa il prezzo per tutti ti arriva l'avviso. Se non vuoi che sappia del tuo interesse, disattiva «Invia una notifica ai proprietari quando aggiungo i loro articoli ai preferiti»."

const ctrWhen = (date, now) => {
  const k = calendarDaysBetween(now, date)
  if (k === 0) return date.getHours() >= 17 ? 'stasera' : 'oggi'
  if (k === 1) return 'domani'
  return formatLongDate(date, now)
}

/**
 * How to buy at his price. «Acquista» shows his price only for a button counter that is still live: a chat price has
 * no offer object, a raised counter shows the new number, an old counter may be gone.
 */
const ctrBuyHow = (state, stale = false) => {
  const S = formatEuro(state.S)
  if (state.chat) return `fai tu un'offerta a ${S} con «Fai un'offerta»`
  if (state.raised && !state.theta) return `riproponi tu ${S} con «Fai un'offerta» (con «Acquista» pagheresti ${formatEuro(state.lastSeller)})`
  if (stale) return `se vedi ancora «Acquista» a ${S} usalo, altrimenti offri tu ${S} con «Fai un'offerta»`
  return `premi «Acquista» a ${S}`
}

const ctrAcceptLabel = (state, stale) => {
  const S = formatEuro(state.S)
  if (state.chat) return `Accetta: fai tu un'offerta a ${S} con «Fai un'offerta»`
  if (state.raised && !state.theta) return `Accetta: riproponi tu ${S} (con «Acquista» pagheresti ${formatEuro(state.lastSeller)})`
  if (stale) return `Accetta: se vedi ancora «Acquista» a ${S} usalo; se il pulsante non c'è più, offri tu ${S}`
  return `${COUNTER_OPTION_LABELS.accept} a ${S}`
}

const ctrBuyFooter = (state, stale) => `${capitalize(ctrBuyHow(state, stale))}, poi paga subito: il messaggio è facoltativo.`

function ctrAcceptOption(state, { stale = false, recommended = false } = {}) {
  const overBudget = state.S > state.Wcap + CTR_EPS
  return {
    id: 'accept', label: ctrAcceptLabel(state, stale), howToBuy: `${capitalize(ctrBuyHow(state, stale))}.`, isRecommended: recommended, price: state.S, isSplit: false, isFinal: false,
    isPrecise: false, wholeEuroFallback: null, stepUpEur: null, stepUpPct: null, stepDownEur: 0, stepDownPct: 0,
    discountFromListPct: ((state.L - state.S) / state.L) * 100, gapShare: null, pAccept: 1, pBelowSeller: null,
    expectedPrice: state.S, expectedSaving: null, totalWithFee: buyerTotal(state.S), landingPoint: state.S, overBudget,
    next: null, apply: null,
  }
}

const ctrNegotiation = (state) => ({
  listPrice: state.L, previousOffer: state.B, firstOffer: state.buyers[0], sellerCounter: state.S, sellerCounterRaw: state.lastSeller, sellerCounterEntered: state.enteredAs,
  round: state.k, buyerCountersSent: state.n, sellerStepEur: state.sigma, sellerStepPct: state.Sprev > 0 ? (state.sigma / state.Sprev) * 100 : 0,
  sellerConcessionShare: state.share, sellerConcessionShareNorm: state.shareNorm, sellerStance: state.stance, sellerStanceLabel: SELLER_STANCES[state.stance].label,
  sellerRaised: state.raised, counterOverOfferPct: (state.S / state.B - 1) * 100, gapEur: ctrR2(state.S - state.B), midpoint: (state.B + state.S) / 2,
  splitTolerance: splitTolerance(state.B, state.S, state.L), receivedAt: state.receivedAt, receivedUncertaintyMinutes: state.unc,
  latencyHours: state.latencyH, minutesSinceCounter: Math.max(0, Math.round(ctrHours(state.receivedAt, state.now) * 60)), tooSoonUntil: state.tMin,
  assumedExpiry: state.assumedExpiry, deadline: state.deadline, planHorizon: state.planHorizon, channel: state.chat ? 'chat' : 'button',
  sellerPriceSurvives: state.theta, maxPrice: state.W,
})

function ctrShortResult(state, warnings, kind, message, { stale = false } = {}) {
  const accept = ctrAcceptOption(state, { stale, recommended: kind === 'accept' || kind === 'accept_counter' })
  const tips = []
  if (kind === 'stop' || kind === 'walk_away') tips.push(ctrFavouriteTip)
  const buyNow = kind === 'accept' || kind === 'accept_counter'
  return {
    ok: true, kind, input: state.input, now: state.now, negotiation: ctrNegotiation(state), message, warnings,
    options: [accept], recommended: buyNow ? accept : null, tips,
    messages: buyNow ? buildAcceptMessages({ stale }) : [], recommendedTone: 'cordiale',
    messageFooter: buyNow ? ctrBuyFooter(state, stale) : null,
    disclaimer: ctrDisclaimer, reminders: [],
  }
}

/* ───────── analysis ───────── */

/**
 * Entry point. Returns { ok: false, errors } or a result whose `kind` is:
 * 'counter' (reply with a price), 'counter_stale' (same, after more than 30 h), 'accept' (countering saves too little),
 * 'accept_counter' (his price is at or below our offer or goal), 'walk_away' (over budget, no room), 'stop' (3 counters sent).
 * options: { preferredSendAt, forcePrice, validityHours } — forcePrice evaluates one price only (the UI's «Applica»).
 */
function analyzeCounter(raw, now = new Date(), options = {}) {
  const norm = normalizeCounterInput(raw, now, options)
  if (!norm.ok) return { ok: false, errors: norm.errors }
  const state = norm.state
  const warnings = norm.warnings
  const { S, B, L } = state

  if (S <= B + CTR_EPS) {
    const extra = S < B - 0.5 ? ' Controlla la cifra: è sotto la tua offerta.' : ''
    return ctrShortResult(state, warnings, 'accept_counter', `È pari o sotto la tua offerta: ${ctrBuyHow(state)} e compra subito.${extra}`)
  }
  if (state.goalPrice != null && S <= state.goalPrice + CTR_EPS) {
    return ctrShortResult(state, warnings, 'accept_counter', `È già al tuo obiettivo: ${ctrBuyHow(state)} e compra subito.`)
  }
  if (state.n >= COUNTER.MAX_BUYER_COUNTERS) {
    return ctrShortResult(state, warnings, 'stop', `Hai già rilanciato tre volte: o compri a ${formatEuro(S)} o lasci perdere e riprovi tra 7–10 giorni.`)
  }
  // Our last offer was announced as the maximum: raising now would make it a bluff and cost credibility.
  if (state.n >= 1 && state.lastBuyerFinal) {
    const message = S <= state.Wcap + CTR_EPS
      ? `Avevi detto che ${formatEuro(B)} era il tuo massimo: rilanciare adesso ti toglierebbe credibilità. Se lo vuoi davvero, ${ctrBuyHow(state)}; altrimenti lascia perdere per ora e segui l'articolo.`
      : `Avevi detto che ${formatEuro(B)} era il tuo massimo e la sua cifra supera il tuo budget: lascia perdere per ora e segui l'articolo.`
    return ctrShortResult(state, warnings, 'stop', message)
  }

  const stale = ctrHours(state.receivedAt, now) > COUNTER.STALE_AFTER_HOURS
  if (stale) state.tMin = ceilToMinutes(addMinutes(now, 5), 5)

  // Candidate prices.
  let cand
  let move = null
  if (state.n >= 1) {
    move = nextCounterMove(state, { cPrev: B, bPrev: state.buyers[state.n - 1], S, Sprev: state.Sprev, n: state.n })
    cand = { mode: 'next', list: move ? [move.price] : [], split: splitPrice(B, S, L) }
  } else {
    cand = ctrFirstCandidates(state)
  }
  if (options.forcePrice != null && Number.isFinite(Number(options.forcePrice))) {
    const forced = ctrR2(Number(options.forcePrice))
    if (forced > B + CTR_EPS && forced < S - CTR_EPS && forced <= state.Wcap + CTR_EPS) {
      if (!cand.list.includes(forced)) cand = { ...cand, mode: cand.mode === 'budget_final' ? 'budget_final' : 'forced' }
      cand = { ...cand, list: [forced] }
    }
  }
  if (!cand.list.length) {
    if (S <= state.Wcap + CTR_EPS) return ctrShortResult(state, warnings, 'accept', `Non c'è spazio per un'altra offerta sensata: ${ctrBuyHow(state, stale || state.expired)}.`, { stale: stale || state.expired })
    return ctrShortResult(state, warnings, 'walk_away', `${formatEuro(S)} supera il tuo massimo e non c'è spazio per un'altra offerta: lascia perdere per ora e segui l'articolo.`)
  }
  const fixedFinal = Boolean(move && move.isFinal)
  const isFinalFor = (price) => fixedFinal || cand.mode === 'budget_final' || (state.n === 0 && state.stance === 'hold' && price !== null)

  // Score every (price, moment) once.
  const slots = buildCounterSlots(state, { stale })
  const evaluations = new Map()
  const evalAt = (price, date) => {
    const key = `${price}|${date.getTime()}`
    if (!evaluations.has(key)) evaluations.set(key, evaluateCounter(state, price, date, { isFinal: isFinalFor(price) }))
    return evaluations.get(key)
  }
  const bestRowAt = (date) => cand.list.map((p) => evalAt(p, date)).reduce((a, b) => (b.expectedPrice < a.expectedPrice - CTR_EPS ? b : a))
  const perSlot = slots.map((s) => {
    const best = bestRowAt(s.date)
    return { ...s, best, E: best.expectedPrice, window: timeWindowAt(s.date) }
  })
  // An inactive seller just replied and may vanish: while he is likely still online any window will do.
  const stillOnline = (s) => state.inactive && ctrHours(state.receivedAt, s.date) <= 2 * COUNTER.INACTIVE_READ_TAU_HOURS
  const eligible = perSlot.filter((s) => s.window.weight >= 0 || stillOnline(s))
  const tolOf = (E) => Math.max(COUNTER.NEAR_TIE_EUR, COUNTER.NEAR_TIE_SHARE * Math.max(0, S - E))
  const pick = (pool) => {
    const best = pool.reduce((a, b) => (b.E < a.E - CTR_EPS ? b : a))
    const threshold = best.E + tolOf(best.E)
    return { best, chosen: pool.filter((s) => s.E <= threshold + CTR_EPS).sort((a, b) => a.date - b.date)[0] }
  }

  let chosen
  let best
  let safeAlternative = null
  let alsoGood = null
  let forced = false
  let reapproach = null
  const onTime = eligible.filter((s) => s.tier === 'on_time')
  const tight = eligible.filter((s) => s.tier === 'tight')
  const late = eligible.filter((s) => s.tier === 'late')
  if (onTime.length) {
    const p = pick(onTime)
    chosen = p.chosen
    best = p.best
    const saving = Math.max(0, S - p.best.E)
    const bestTight = tight.length ? pick(tight).best : null
    const bestLate = late.length ? pick(late).best : null
    if (bestTight && bestTight.E < p.best.E - Math.max(COUNTER.TIGHT_GAIN_EUR, COUNTER.TIGHT_GAIN_SHARE * saving)) {
      safeAlternative = chosen
      chosen = bestTight
      best = bestTight
    } else if (bestLate && bestLate.E < p.best.E - Math.max(COUNTER.LATE_GAIN_EUR, COUNTER.LATE_GAIN_SHARE * saving)) {
      safeAlternative = chosen
      chosen = bestLate
      best = bestLate
    } else {
      const better = [bestTight, bestLate].filter(Boolean).sort((a, b) => a.E - b.E)[0]
      if (better && better.E < chosen.E - tolOf(chosen.E)) alsoGood = better
    }
  } else if (eligible.length) {
    const p = pick(eligible)
    chosen = p.chosen
    best = p.best
  } else if (perSlot.length) {
    const pool = perSlot.filter((s) => s.tier === 'on_time')
    const p = pick(pool.length ? pool : perSlot)
    chosen = p.best
    best = p.best
    forced = true
  } else {
    // Nothing between now and the horizon (e.g. a counter received at night, reopened the next night):
    // the first polite moment out of quiet hours, with its real tier.
    const date = ctrQuiet(state.tMin) ? ctrOutOfQuiet(state.tMin) : state.tMin
    const tier = !state.assumedExpiry || stale ? 'on_time' : date <= state.deadline ? 'on_time' : date <= state.assumedExpiry ? 'tight' : 'late'
    const row = bestRowAt(date)
    chosen = { date, kind: date.getTime() - now.getTime() <= 10 * 60_000 ? 'now' : 'min_delay', tier, daysWaited: calendarDaysBetween(now, date), windowId: timeWindowAt(date).id, best: row, E: row.expectedPrice, window: timeWindowAt(date) }
    best = chosen
    forced = tier !== 'late'
  }
  let pinned = false
  if (options.preferredSendAt) {
    const wanted = new Date(options.preferredSendAt).getTime()
    const near = [...eligible].sort((a, b) => Math.abs(a.date.getTime() - wanted) - Math.abs(b.date.getTime() - wanted))[0]
    if (near && Math.abs(near.date.getTime() - wanted) <= 3 * 3_600_000) {
      chosen = near
      pinned = true
      safeAlternative = null
      alsoGood = null
    }
  }
  if (forced) {
    const from = ceilToMinutes(addMinutes(state.planHorizon, 1), 5)
    const after = buildCounterSlots(state, { from, until: addMinutes(state.planHorizon, 24 * 60) })
      .filter((s) => timeWindowAt(s.date).weight >= 0)
      .map((s) => {
        const row = bestRowAt(s.date)
        return { ...s, best: row, E: row.expectedPrice, window: timeWindowAt(s.date) }
      })
    reapproach = after.length ? pick(after).chosen : null
  }

  // Options at the chosen moment.
  const rows = cand.list.map((p) => evalAt(p, chosen.date)).sort((a, b) => a.price - b.price)
  const bestE = Math.min(...rows.map((r) => r.expectedPrice))
  const saving = Math.max(0, S - bestE)
  const balanced = rows.find((r) => r.expectedPrice <= bestE + CTR_EPS)
  const boldRow = rows.find((r) => r.expectedPrice <= bestE + COUNTER.BOLD_BAND_SHARE * saving + CTR_EPS && r.score.gapShare >= COUNTER.BOLD_MIN_SHARE - CTR_EPS)
  const bold = boldRow && balanced.price - boldRow.price >= state.minStep - CTR_EPS ? boldRow : null
  const splitRow = rows.find((r) => r.score.isSplit)
  const splitOption = splitRow && splitRow !== balanced && splitRow.price > balanced.price ? splitRow : null
  const thetaAcc = Math.max(L < COUNTER.SMALL_ITEM_EUR ? COUNTER.MIN_SAVING_EUR_SMALL : COUNTER.MIN_SAVING_EUR, (COUNTER.MIN_SAVING_PCT / 100) * S)
  const acceptWins = options.forcePrice == null && S <= state.Wcap + CTR_EPS && S - balanced.expectedPrice < thetaAcc
  const kind = stale ? 'counter_stale' : acceptWins ? 'accept' : 'counter'

  // Re-score the reported moments at the recommended price, so that their differences mean something.
  const recPrice = balanced.price
  const view = (slot) => {
    if (!slot) return null
    const e = evalAt(recPrice, slot.date)
    return {
      date: slot.date, kind: slot.kind, tier: slot.tier, daysWaited: slot.daysWaited, windowId: slot.windowId, score: e.score,
      pAccept: e.pAccept, pAvailable: e.pAvailable, pOverall: e.pAccept * e.pAvailable, expectedPrice: e.expectedPrice, bestPriceHere: slot.best.price,
      expiresAt: addMinutes(slot.date, VINTED.OFFER_VALIDITY_HOURS * 60),
    }
  }
  const optimal = view(chosen)
  const nowRow = perSlot.find((s) => s.kind === 'now')
  const nowView = view(nowRow || { date: state.tMin, kind: 'min_delay', tier: 'on_time', daysWaited: calendarDaysBetween(now, state.tMin), windowId: timeWindowAt(state.tMin).id, best: balanced })

  // "Adesso?"
  const nowWindow = timeWindowAt(now)
  const minutesSince = Math.max(0, Math.round(ctrHours(state.receivedAt, now) * 60))
  let reason
  if (chosen.kind === 'now') reason = 'chosen'
  else if (now < addMinutes(state.receivedAt, state.minDelayMinutes)) reason = 'too_soon'
  else if (nowWindow.weight < 0) reason = 'avoid_window'
  else if (!nowRow) reason = 'quiet'
  else if (nowRow.E <= chosen.E + tolOf(chosen.E) || nowView.expectedPrice - optimal.expectedPrice < 0.01) reason = 'close_enough'
  else reason = 'worse'
  const deltaPoints = Math.round((nowView.pAccept - optimal.pAccept) * 100)
  const optimalAt = isSameDay(optimal.date, now) ? `alle ${formatTime(optimal.date)}` : `${formatLongDate(optimal.date, now)} alle ${formatTime(optimal.date)}`
  const nowText = {
    chosen: 'Adesso è il momento giusto: invia ora.',
    too_soon: `Adesso no: ti ha risposto ${minutesSince <= 1 ? 'un minuto' : `${minutesSince} minuti`} fa. Rispondere a caldo gli dice che hai fretta: aspetta almeno fino alle ${formatTime(state.tMin)}.`,
    avoid_window: `Adesso no: è ${nowWindow.label.toLowerCase()}, una fascia sfavorevole per trattare.`,
    quiet: "Adesso no: è tardi, meglio non scrivergli a quest'ora.",
    close_enough: 'Puoi anche inviare adesso: la differenza è minima.',
    worse: deltaPoints < 0
      ? `Adesso andrebbe, ma ${optimalAt} hai ${formatPoints(-deltaPoints).replace(/^\+/, '')} in più.`
      : `Adesso andrebbe, ma ${optimalAt} in media paghi ${formatEuro(nowView.expectedPrice - optimal.expectedPrice)} in meno.`,
  }[reason]
  const sendNow = {
    ok: reason === 'chosen' || reason === 'close_enough', reason, text: nowText, deltaPoints, slot: nowView, window: nowView.score.timeWindow,
    windowEndsAt: addMinutes(startOfDay(nowView.date), nowView.score.timeWindow.to),
  }

  const verdict = buildVerdict(optimal, sendNow, now, view(best), { subject: 'la nuova offerta' })
  const timing = {
    tier: optimal.tier, pastAssumedExpiry: optimal.tier === 'late', deadlineForcesBadWindow: forced, stale,
    expiryImminent: Boolean(state.deadline && state.deadline > now && ctrHours(now, state.deadline) <= 1),
  }
  const others = []
  const seenDays = new Set([startOfDay(chosen.date).getTime()])
  for (const s of [...eligible].sort((a, b) => a.E - b.E)) {
    const key = startOfDay(s.date).getTime()
    if (seenDays.has(key)) continue
    seenDays.add(key)
    others.push(s)
  }
  const spreadPool = [optimal, view(alsoGood), ...others.map(view)].filter(Boolean).map((v) => v.pAccept)
  timing.spread = spreadPool.length ? Math.max(...spreadPool) - Math.min(...spreadPool) : 0
  timing.timingMatters = timing.spread >= TIMING_MATTERS_SPREAD
  timing.otherMoments = others.slice(0, 3).map(view).sort((a, b) => a.date - b.date)

  // Options.
  const optionFrom = (row, id) => {
    const after = row.after
    const ifHolds = after.vHold.action === 'counter'
      ? { action: 'counter', price: after.vHold.price, isFinal: after.vHold.isFinal, isSplit: after.vHold.isSplit, pAccept: after.vHold.pAccept, sellerPrice: S }
      : { action: 'accept', price: S, sellerPrice: S }
    const ifMoves = after.vMove.action === 'counter'
      ? { action: 'counter', sellerPrice: after.S2, price: after.vMove.price, isFinal: after.vMove.isFinal, isSplit: after.vMove.isSplit, pAccept: after.vMove.pAccept }
      : { action: 'accept', sellerPrice: after.S2, price: after.S2 }
    const isSplit = row.score.isSplit
    const chosenByUser = id === 'balanced' && options.forcePrice != null
    const label = chosenByUser
      ? 'La tua scelta'
      : id === 'balanced'
        ? (acceptWins ? (isSplit ? COUNTER_OPTION_LABELS.split : 'Nuova offerta') : isSplit ? `${COUNTER_OPTION_LABELS.split} · consigliata` : COUNTER_OPTION_LABELS.balanced)
        : COUNTER_OPTION_LABELS[id]
    const whole = Math.abs(row.price - Math.round(row.price)) > 1e-6 ? wholeEuroFallback(row.price) : null
    return {
      id, label, isRecommended: false, isChosen: chosenByUser, price: row.price, isSplit, isFinal: row.isFinal, isPrecise: isPrecisePrice(row.price, L), wholeEuroFallback: whole,
      stepUpEur: ctrR2(row.price - B), stepUpPct: ((row.price - B) / B) * 100, stepDownEur: ctrR2(S - row.price), stepDownPct: ((S - row.price) / S) * 100,
      discountFromListPct: ((L - row.price) / L) * 100, gapShare: row.score.gapShare, pAccept: row.pAccept, pBelowSeller: row.pBelowSeller,
      expectedPrice: row.expectedPrice, expectedSaving: S <= state.Wcap + CTR_EPS ? S - row.expectedPrice : null, totalWithFee: buyerTotal(row.price),
      landingPoint: (row.price + S) / 2, overBudget: false, next: row.isFinal ? { final: true, ifHolds: null, ifMoves: null } : { final: false, ifHolds, ifMoves },
      apply: { counterPrice: row.price, preferredSendAt: optimal.date },
      // For the monthly learning loop: the engine's logit before the learned correction, at the planned moment.
      learning: { rawLogit: row.score.rawLogit, learnedWeight: row.score.learnedWeight, pRead: row.pRead, windowId: row.score.timeWindow ? row.score.timeWindow.id : null },
    }
  }
  const balancedOption = optionFrom(balanced, 'balanced')
  const acceptOption = ctrAcceptOption(state, { stale: stale || state.expired, recommended: acceptWins })
  const optionList = [bold && optionFrom(bold, 'bold'), balancedOption, splitOption && optionFrom(splitOption, 'split'), acceptOption].filter(Boolean)
  const recommended = acceptWins ? acceptOption : balancedOption
  if (!acceptWins && options.forcePrice == null) balancedOption.isRecommended = true

  // Factors at the recommended price and moment.
  const recRow = evalAt(recPrice, optimal.date)
  const factors = attributeFactors(recRow.score)
  const uncertainty = uncertaintyFor(state.input)
  const probability = acceptWins ? 1 : recRow.pAccept

  const ctx = { state, stale, optimal, balanced: balancedOption, bold: bold ? optionList.find((o) => o.id === 'bold') : null, acceptWins, saving: S - balanced.expectedPrice, forced, reapproach: view(reapproach), safeAlternative: view(safeAlternative), alsoGood: view(alsoGood), cand }
  const lines = ctrLines(ctx)
  const isSplit = balancedOption.isSplit
  const isFinal = balancedOption.isFinal
  const messages = acceptWins
    ? buildAcceptMessages({ stale })
    : buildCounterMessages({ itemTitle: state.input.itemTitle, price: recPrice, previousOffer: B, firstOffer: state.buyers[0], sendAt: optimal.date, isSplit, isFinal, stale, total: buyerTotal(recPrice) })
  const recommendedTone = acceptWins ? 'cordiale' : recommendedCounterToneFor({ isSplit, isFinal, stance: state.stance, premium: state.input.category.premium })
  const hero = acceptWins
    ? { title: `Accetta e compra a ${formatEuro(S)}`, sublabel: `${capitalize(ctrBuyHow(state, stale || state.expired))} adesso: aspettare non fa risparmiare e qualcuno potrebbe comprarlo prima.` }
    : { title: `Rispondi con ${formatEuro(recPrice)}`, sublabel: verdict.headline }

  const result = {
    ok: true, kind, input: state.input, now, warnings, negotiation: ctrNegotiation(state),
    options: optionList, recommended, optimal, best: view(best), alsoGood: view(alsoGood), safeAlternative: view(safeAlternative), reapproach: view(reapproach),
    nowSlot: nowView, sendNow, pinned, timing, verdict: { ...verdict, hero }, probability,
    probabilityRange: [Math.max(0.01, probability - uncertainty), Math.min(0.99, probability + uncertainty)],
    components: { pAccept: recRow.score.pAccept, pAvailable: recRow.pAvailable, pRead: recRow.pRead },
    factors: { ...factors, baseLabel: `Il tuo passo: ${ctrIl(recRow.score.gapShare * 100)}${Math.round(recRow.score.gapShare * 100)}% della distanza` },
    candidates: { mode: cand.mode, prices: cand.list, lo: cand.lo ?? null, hi: cand.hi ?? null },
    reasons: ctrReasons(ctx), tips: ctrTips(ctx), ladder: lines.ladder, plan: lines.plan, lines,
    messages, recommendedTone, messageBeforeOffer: false,
    messageFooter: acceptWins ? ctrBuyFooter(state, stale || state.expired) : "Prima invia la nuova offerta con «Fai un'offerta» nella chat, poi incolla subito il messaggio.",
    avoidToday: avoidWindowsOn(optimal.date), nowInAvoid: nowWindow.weight < 0, disclaimer: ctrDisclaimer,
  }
  result.reminders = buildCounterReminders(result)
  return result
}

/* ───────── explanation strings ───────── */

function ctrLines(ctx) {
  const { state, optimal, balanced, bold, stale } = ctx
  const { L, S, B } = state
  const now = state.now
  const price = balanced.price
  const over = (x) => x > state.Wcap + CTR_EPS
  const maxText = state.W != null ? formatEuro(state.W) : ''
  const lines = {}

  // Deadline: never promise a button that may be gone or that shows another price.
  if (state.chat) lines.deadline = "Te l'ha scritta in chat: non scade, ma intanto qualcun altro può comprarlo."
  else if (stale) lines.deadline = `Sono passate più di ${COUNTER.STALE_AFTER_HOURS} ore: ${ctrBuyHow(state, true)}. Una tua nuova cifra vale come una nuova offerta.`
  else if (state.expired) lines.deadline = `La sua proposta potrebbe essere già scaduta (alle ${formatTime(state.assumedExpiry)}; Vinted non indica una scadenza ufficiale): ${ctrBuyHow(state, true)}.`
  else if (state.assumedExpiry) lines.deadline = `La sua proposta potrebbe scadere ${formatLongDate(state.assumedExpiry, now)} alle ${formatTime(state.assumedExpiry)} (Vinted non indica una scadenza ufficiale): finché non rispondi ${state.raised && !state.theta ? `puoi riproporgli tu ${formatEuro(S)}` : `puoi ancora comprarla a ${formatEuro(S)} con «Acquista»`}.`
  else lines.deadline = `Vinted non indica una scadenza ufficiale: finché non rispondi ${state.raised && !state.theta ? `puoi riproporgli tu ${formatEuro(S)}` : `puoi comprarla a ${formatEuro(S)} con «Acquista»`}, ma intanto qualcun altro può comprarlo.`

  if (over(S)) lines.risk = `La sua cifra è sopra il tuo massimo (${maxText}): se la tua offerta non passa, lasci perdere senza aver perso nulla.`
  else if (state.theta) lines.risk = `La sua cifra resta disponibile: se la tua nuova offerta non passa, puoi ancora ${state.chat ? `offrirgli tu ${formatEuro(S)}` : `comprare a ${formatEuro(S)}`}.`
  else if (L - S < 0.009) lines.risk = `È fermo al prezzo pieno: se la tua offerta non passa, puoi sempre comprare a ${formatEuro(L)}${over(L) ? ', ma è sopra il tuo massimo' : ''}.`
  else if (over(L)) lines.risk = `Inviando la nuova offerta, la sua proposta a ${formatEuro(S)} potrebbe non essere più acquistabile: nel caso peggiore gliela riproponi tu.`
  else lines.risk = `Inviando la nuova offerta, la sua proposta a ${formatEuro(S)} potrebbe non essere più acquistabile: nel caso peggiore gliela riproponi tu o compri a ${formatEuro(L)}. Rischi al massimo ${formatEuro(L - S)}.`

  lines.totals = ctx.acceptWins
    ? `Con la commissione Vinted (${VINTED.BUYER_FEE_PCT}% + ${formatEuro(VINTED.BUYER_FEE_FIXED)}) paghi ${formatEuro(buyerTotal(S))}, spedizione esclusa.`
    : `Con la commissione Vinted (${VINTED.BUYER_FEE_PCT}% + ${formatEuro(VINTED.BUYER_FEE_FIXED)}) paghi ${formatEuro(buyerTotal(price))} invece di ${formatEuro(buyerTotal(S))}, spedizione esclusa.`

  if (ctx.alsoGood && !ctx.acceptWins) {
    const d = Math.round((ctx.alsoGood.pAccept - optimal.pAccept) * 100)
    const at = isSameDay(ctx.alsoGood.date, optimal.date) ? `Alle ${formatTime(ctx.alsoGood.date)}` : `${capitalize(formatLongDate(ctx.alsoGood.date, now))} alle ${formatTime(ctx.alsoGood.date)}`
    const gain = formatPoints(d).replace(/^\+/, '')
    if (d > 0) {
      if (ctx.alsoGood.tier === 'on_time') lines.alsoGood = `${at} avresti ${gain} in più.`
      else if (ctx.alsoGood.tier === 'tight') lines.alsoGood = `${at} avresti ${gain} in più, ma sei a ridosso delle ${state.validityHours} ore: la sua proposta potrebbe scadere alle ${formatTime(state.assumedExpiry)}.`
      else lines.alsoGood = `${at} avresti ${gain} in più, ma sei oltre le ${state.validityHours} ore: la sua proposta potrebbe essere già scaduta (alle ${formatTime(state.assumedExpiry)}).`
    }
  }

  if (optimal.tier === 'tight') {
    const expiry = state.assumedExpiry ? ` (la sua proposta potrebbe scadere alle ${formatTime(state.assumedExpiry)})` : ''
    lines.tier = ctx.safeAlternative
      ? `È al limite delle ${state.validityHours} ore${expiry}: se preferisci stare sul sicuro, ${formatLongDate(ctx.safeAlternative.date, now)} alle ${formatTime(ctx.safeAlternative.date)} (${formatPoints(Math.round((ctx.safeAlternative.pAccept - optimal.pAccept) * 100))}).`
      : `È al limite delle ${state.validityHours} ore${expiry}: se puoi, rispondi prima.`
  } else if (optimal.tier === 'late') {
    lines.tier = `Dopo le ${state.validityHours} ore la sua proposta potrebbe non valere più: la tua sarà letta come una nuova offerta.`
  }
  if (ctx.forced) {
    const re = ctx.reapproach ? `${formatLongDate(ctx.reapproach.date, now)} alle ${formatTime(ctx.reapproach.date)}` : 'nei prossimi giorni'
    const when = optimal.kind === 'now' ? 'adesso' : `${ctrWhen(optimal.date, now)} alle ${formatTime(optimal.date)}`
    lines.tier = `La sua proposta potrebbe scadere prima della prossima fascia buona: rispondi ${when}, oppure riprova come nuova offerta ${re}.`
  }

  if (bold && !ctx.acceptWins) {
    lines.whyNotLower = `Puoi tentare ${formatEuro(bold.price)}: se accetta risparmi altri ${formatEuro(price - bold.price)}, ma succede circa ${ctrIl(bold.pAccept * 100)}${toPercent(bold.pAccept)}% delle volte e in media pagheresti ${formatEuro(bold.expectedPrice)}.`
  }

  // E dopo? Every price it names is checked against the budget, and the way to buy matches the channel.
  if (ctx.acceptWins) {
    lines.plan = [`Compra subito: ${ctrBuyHow(state, stale || state.expired)} (${formatEuro(buyerTotal(S))} con la commissione). Chi paga per primo se lo aggiudica.`]
  } else {
    const plan = [`Se accetta: paga subito (${formatEuro(buyerTotal(price))}).`]
    const next = balanced.next
    const holdAccept = over(S)
      ? `è sopra il tuo massimo (${maxText}): lascia perdere e segui l'articolo`
      : `${ctrBuyHow(state)}, se lo vuoi ancora`
    if (next && next.final) {
      plan.push(`Se resta a ${formatEuro(S)}: era la tua ultima offerta. ${over(S) ? `È sopra il tuo massimo: lascia perdere e segui l'articolo.` : `${capitalize(ctrBuyHow(state))} se lo vuoi ancora, altrimenti lascia stare per qualche giorno.`}`)
    } else if (next) {
      plan.push(next.ifHolds.action === 'counter'
        ? `Se resta a ${formatEuro(S)}: ${next.ifHolds.isFinal ? 'ultima offerta' : 'rilancia a'} ${formatEuro(next.ifHolds.price)}${next.ifHolds.isFinal ? ', poi basta' : ''}.`
        : `Se resta a ${formatEuro(S)}: ${holdAccept}.`)
      const moved = ctrApprox(next.ifMoves.sellerPrice, L)
      plan.push(next.ifMoves.action === 'counter'
        ? `Se scende verso ${moved}: ${next.ifMoves.isSplit ? 'chiudi a metà strada, circa' : next.ifMoves.isFinal ? 'ultima offerta, circa' : 'sali a circa'} ${ctrApprox(next.ifMoves.price, L)}.`
        : over(next.ifMoves.sellerPrice) ? `Se scende verso ${moved}: è ancora sopra il tuo massimo, lascia stare.` : `Se scende verso ${moved}: accetta.`)
    }
    const refusal = []
    if (!over(S)) refusal.push(L - S < 0.009 ? `compra a ${formatEuro(L)} con «Acquista»` : state.theta ? (state.chat ? `offrigli tu ${formatEuro(S)} con «Fai un'offerta»` : `compra a ${formatEuro(S)} con «Acquista»`) : `riproponi ${formatEuro(S)}`)
    if (!state.theta && L - S >= 0.009 && !over(L)) refusal.push(`compra a ${formatEuro(L)}`)
    plan.push(refusal.length ? `Se rifiuta: ${refusal.join(' o ')}, se lo vuoi ancora.` : "Se rifiuta: lascia perdere per ora e segui l'articolo.")
    lines.plan = plan
  }

  // Ladder: every step with euros and percentages.
  const first = state.buyers[0]
  const steps = [`Listino ${formatEuro(L)}`, `tua offerta ${formatEuro(first)} (−${ctrPct(((L - first) / L) * 100)}%)`]
  for (let i = 0; i < state.sellers.length; i++) {
    const s = Math.min(state.sellers[i], i === 0 ? L : state.sellers[i - 1])
    const b = state.buyers[i]
    const fromList = ((L - s) / L) * 100
    steps.push(`sua controproposta ${formatEuro(s)} (+${ctrPct((s / b - 1) * 100)}% sulla tua, −${ctrPct(fromList)}% dal listino)`)
    if (i + 1 < state.buyers.length) steps.push(`tua offerta ${formatEuro(state.buyers[i + 1])}`)
  }
  if (!ctx.acceptWins) {
    steps.push(`tua nuova offerta ${formatEuro(price)} (+${formatEuro(price - B)}, +${ctrPct(((price - B) / B) * 100)}%; −${formatEuro(S - price)}, −${ctrPct(((S - price) / S) * 100)}% dalla sua)`)
    const next = balanced.next
    if (next && !next.final && next.ifHolds.action === 'counter' && next.ifHolds.isFinal) steps.push(`se resta fermo, ultima offerta ${formatEuro(next.ifHolds.price)}`)
  }
  lines.ladder = `${steps.join(' → ')}.`
  return lines
}

function ctrReasons(ctx) {
  const { state, optimal, balanced, acceptWins } = ctx
  const out = []
  const now = state.now
  const sharePct = Math.round(state.share * 100)
  const typical = Math.round(COUNTER.ROUND_MEAN_SHARE[Math.min(state.k - 1, COUNTER.ROUND_MEAN_SHARE.length - 1)] * counterShareOf(state.input.profile) * 20) * 5
  const sigma = formatEuro(state.sigma)
  const share = `${ctrIl(sharePct)}${sharePct}% della distanza`
  if (acceptWins) {
    out.push(ctx.saving < 0.01
      ? `Rilanciare non ti farebbe risparmiare nulla in media: accetta e ${ctrBuyHow(state, ctx.stale || state.expired)} adesso.`
      : `In media risparmieresti solo ${formatEuro(ctx.saving)}: accetta e ${ctrBuyHow(state, ctx.stale || state.expired)} adesso.`)
  }
  // The seller: a description, plus advice only when we are going to counter.
  if (state.raised) out.push(`Ha alzato la cifra rispetto alla sua proposta precedente: non inseguirlo, ragioniamo sui ${formatEuro(state.S)}.`)
  else if (state.stance === 'hold') {
    const what = state.sigma < 0.01 ? 'Il venditore non è sceso affatto' : `Il venditore è sceso solo di ${sigma}, quasi niente`
    out.push(acceptWins ? `${what}.` : `${what}: fai una sola offerta finale, poi lascia stare per qualche giorno.`)
  } else if (state.stance === 'firm') out.push(`Il venditore è sceso solo di ${sigma} (${share}; di solito si scende del ${typical}% circa)${acceptWins ? '.' : ': è rigido e difficilmente scenderà ancora da solo.'}`)
  else if (state.stance === 'moving') out.push(`Il venditore è sceso di ${sigma} (${share})${acceptWins ? '.' : ': è disposto a trattare, ma non ha fretta.'}`)
  else out.push(`Il venditore è sceso di ${sigma} (${share}): è pronto a chiudere.${!acceptWins && !balanced.isSplit && !balanced.isFinal ? ' Puoi salire poco e lasciare che scenda ancora.' : ''}`)
  if (acceptWins) return out.slice(0, 3)

  const price = formatEuro(balanced.price)
  const gapPct = Math.round(balanced.gapShare * 100)
  if (balanced.isFinal) {
    if (ctx.cand.mode === 'budget_final') out.push(`È la tua ultima offerta: ${price} è il massimo del budget che hai indicato.`)
    else if (state.n === 0) out.push('È la tua ultima offerta: la sua cifra non si è mossa, quindi fai un solo passo chiaro e fermati.')
    else out.push('È la tua ultima offerta: un passo più piccolo del precedente gli fa capire che sei al limite.')
  } else if (balanced.isSplit) {
    const lower = ctx.cand.list.some((p) => p < balanced.price - CTR_EPS)
    out.push(`${price} è a metà strada tra la tua offerta e la sua: è la proposta che i venditori accettano più spesso.${lower ? ' Salire di meno farebbe scendere molto le probabilità e in media pagheresti di più.' : ''}`)
  } else {
    out.push(`Sali di ${formatEuro(balanced.stepUpEur)} (+${ctrPct(balanced.stepUpPct)}%), ${ctrIl(gapPct)}${gapPct}% della distanza: abbastanza per farlo rispondere, senza regalargli la metà strada.`)
  }

  const window = optimal.score.timeWindow
  const when = ctrWhen(optimal.date, now)
  const hoursAfter = optimal.score.hoursAfter
  const at = `${when} alle ${formatTime(optimal.date)}`
  if (ctx.forced) out.push(`Rispondi ${optimal.kind === 'now' ? 'adesso' : at}: dopo, la sua proposta potrebbe essere scaduta.`)
  else if (state.inactive) out.push(hoursAfter <= 2 ? `Entra di rado: rispondi mentre è ancora online, ${at}.` : `Entra di rado: rispondi ${at}, quando è più probabile che riapra l'app.`)
  else if (hoursAfter >= 12) out.push(`Rispondere dopo qualche ora, ${at} (${window.label.toLowerCase()}), aumenta le accettazioni: una risposta immediata segnala fretta.`)
  else if (optimal.kind === 'now') out.push(`Rispondi adesso: è passata almeno un'ora dalla sua risposta e sei in una fascia ${window.weight > 0 ? 'favorevole' : 'neutra'}.`)
  else out.push(`Rispondi ${at} (${window.label.toLowerCase()}): è passata almeno un'ora dalla sua risposta e aspettare oltre non migliora il prezzo atteso.`)
  return out.slice(0, 3)
}

function ctrTips(ctx) {
  const { state, optimal, balanced, stale } = ctx
  const tips = []
  if (state.stance === 'hold' && !ctx.acceptWins) {
    tips.push(state.sigma < 1
      ? "Non si è mosso di un euro: se rifiuta, metti il cuore all'articolo e riprova tra 7–10 giorni; le offerte fatte più avanti ottengono prezzi migliori."
      : "È sceso pochissimo: se rifiuta, metti il cuore all'articolo e riprova tra 7–10 giorni; le offerte fatte più avanti ottengono prezzi migliori.")
  }
  const pLost = 1 - optimal.pAvailable
  if (pLost >= 0.05 && !ctx.acceptWins) tips.push(`C'è circa ${ctrIl(pLost * 100)}${toPercent(pLost)}% di probabilità che qualcun altro lo compri prima: se ci tieni molto, ${state.S <= state.Wcap + CTR_EPS ? `compralo ora a ${formatEuro(state.S)}` : 'non aspettare troppo'}.`)
  if (!ctx.acceptWins && balanced.wholeEuroFallback != null) tips.push(`Se Vinted non accetta i centesimi, usa ${formatEuro(balanced.wholeEuroFallback)}.`)
  if (ctx.forced) tips.push(`La sua proposta potrebbe scadere prima della prossima fascia buona: se non puoi rispondere ${optimal.kind === 'now' ? 'adesso' : `alle ${formatTime(optimal.date)}`}, riprova più tardi come nuova offerta${ctx.reapproach ? ` (${formatLongDate(ctx.reapproach.date, state.now)} alle ${formatTime(ctx.reapproach.date)})` : ''}.`)
  if (stale) tips.push('Sono passate molte ore: se il venditore non risponde entro un giorno, scrivigli due righe senza cambiare cifra.')
  tips.push(ctrFavouriteTip)
  return tips
}

/* ───────── reminders ───────── */

const ctrOutOfQuiet = (date) => {
  const m = minutesOfDay(date)
  if (m >= COUNTER.QUIET_FROM_MINUTES) return atTime(addDays(startOfDay(date), 1), 0, COUNTER.QUIET_TO_MINUTES)
  if (m < COUNTER.QUIET_TO_MINUTES) return atTime(startOfDay(date), 0, COUNTER.QUIET_TO_MINUTES)
  return date
}

/** First moment ≥ date inside a positive window (scanning the next three days), else the date itself. */
const ctrNextPositive = (date) => {
  if (timeWindowAt(date).weight > 0) return date
  for (let d = 0; d <= 3; d++) {
    const day = addDays(startOfDay(date), d)
    const starts = TIME_WINDOWS.filter((w) => w.weight > 0 && w.days.includes(effectiveWeekday(day))).map((w) => atTime(day, 0, w.from + 5)).sort((a, b) => a - b)
    const hit = starts.find((t) => t.getTime() >= date.getTime())
    if (hit) return hit
  }
  return date
}

/**
 * Local notifications for the plan. Before sending: «invia la nuova offerta» 10 minutes before the moment and, when an
 * expiry is assumed, a last call 15 minutes before it. After «Ho inviato» (`sentAt`): a nudge after 24 h (in a good
 * window) and a give-up note after 72 h. Nothing fires in quiet hours (moved to 07:00; a deadline call is dropped).
 */
function buildCounterReminders(result, { sentAt = null, title = null } = {}) {
  if (!result || !result.ok || !result.optimal) return []
  const name = (title ?? (result.input && result.input.itemTitle)) || "l'articolo"
  const price = result.recommended && result.recommended.id !== 'accept' ? formatEuro(result.recommended.price) : null
  const out = []
  if (!sentAt) {
    if (price) {
      const at0 = addMinutes(result.optimal.date, -10)
      let at = ctrQuiet(at0) ? ctrOutOfQuiet(at0) : at0
      if (at.getTime() > result.optimal.date.getTime()) at = at0
      out.push({ kind: 'counter_send', at, title: 'Tra 10 minuti: invia la nuova offerta', body: `${name}: proponi ${price} con il messaggio pronto.${result.optimal.tier === 'tight' ? ' È al limite delle 24 ore.' : ''}` })
    }
    const expiry = result.negotiation.assumedExpiry
    if (expiry) {
      const at = addMinutes(expiry, -15)
      const m = minutesOfDay(at)
      const quiet = m >= COUNTER.QUIET_FROM_MINUTES || m < COUNTER.QUIET_TO_MINUTES
      if (!quiet && at.getTime() > addMinutes(result.optimal.date, 10).getTime()) {
        out.push({ kind: 'counter_deadline', at, title: 'La sua controproposta potrebbe scadere', body: `Rispondi o accettala entro le ${formatTime(expiry)}.` })
      }
    }
    return out
  }
  const sent = new Date(sentAt)
  out.push({ kind: 'counter_followup', at: ctrOutOfQuiet(ctrNextPositive(addMinutes(sent, COUNTER.FOLLOWUP_HOURS * 60))), title: `Nessuna risposta per ${name}?`, body: 'Mandagli due righe: non serve una nuova offerta.' })
  out.push({ kind: 'counter_giveup', at: ctrOutOfQuiet(addMinutes(sent, COUNTER.GIVEUP_HOURS * 60)), title: 'Trattativa ferma', body: "Segui l'articolo con il cuore e riprova tra qualche giorno." })
  return out
}

// ───────────────────────── src/core/extract.js ─────────────────────────
/**
 * Extraction from a Vinted item page and mapping onto the analyzer's form.
 * Pure string parsing (no DOM): works in Node, the browser and React Native.
 *
 * What a public item page contains server-side (verified October 2026):
 * - JSON-LD Product: name, description, brand, price, currency, condition, category path, color.
 * - data-testid="seller-last-logged-in": "Ultima visita 26 min fa".
 * - data-testid="profile-username" and a rating aria-label "valutazione di 5 su 5 stelle".
 * - itemProp="upload_date": "un minuto fa", "3 giorni fa", "2 settimane fa"…
 */


const CONDITION_LABELS = { New: 'nuovo con etichetta', NewWithTags: 'nuovo con etichetta', NewWithoutTags: 'nuovo senza etichetta', Used: 'usato', Refurbished: 'ricondizionato', Damaged: 'danneggiato' }

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ' }

const decodeEntities = (s) => String(s || '')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&([a-z]+);/gi, (m, name) => (ENTITIES[name.toLowerCase()] !== undefined ? ENTITIES[name.toLowerCase()] : m))

const stripTags = (s) => decodeEntities(String(s || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim()

const NUMBER_WORDS = { un: 1, una: 1, "un'": 1, uno: 1, due: 2, tre: 3, quattro: 4, cinque: 5, sei: 6, sette: 7, otto: 8, nove: 9, dieci: 10 }

/**
 * "26 min fa", "un'ora fa", "ieri", "3 giorni fa", "una settimana fa", "2 mesi fa", "un anno fa"
 * → elapsed days (fractional), or null when unparseable. Prefixes like "Ultima visita" / "Caricato" are ignored.
 */
function parseRelativeItalian(text) {
  const t = String(text || '').toLowerCase().replace(/[’]/g, "'").trim()
  if (!t) return null
  if (/\b(adesso|ora|poco fa|un attimo fa)\b/.test(t) && !/\bun'?ora\b/.test(t)) return 0
  if (/\bieri\b/.test(t)) return 1
  if (/\boggi\b/.test(t)) return 0
  const m = t.match(/(\d+|un'|un|una|uno|due|tre|quattro|cinque|sei|sette|otto|nove|dieci)\s*(secondi?|sec|minut[oi]|min|or[ae]|giorn[oi]|gg|settiman[ae]|sett|mes[ei]|ann[oi])\b/)
  if (!m) return null
  const raw = m[1].replace(/\s/g, '')
  const n = /^\d+$/.test(raw) ? Number(raw) : NUMBER_WORDS[raw] || 1
  const unit = m[2]
  if (/^sec/.test(unit)) return n / 86_400
  if (/^min/.test(unit)) return n / 1_440
  if (/^or/.test(unit)) return n / 24
  if (/^(giorn|gg)/.test(unit)) return n
  if (/^sett/.test(unit)) return n * 7
  if (/^mes/.test(unit)) return n * 30
  if (/^ann/.test(unit)) return n * 365
  return null
}

const firstMatch = (html, re) => {
  const m = html.match(re)
  return m ? m[1] : null
}

/** Parses the HTML of a Vinted item page. Every field may be null; `found`/`missing` list what was recognised. */
function parseVintedItemHtml(html) {
  const src = String(html || '').replace(/<!--[\s\S]*?-->/g, '')
  const out = {
    title: null, listPrice: null, currency: null, brand: null, condition: null, categoryText: null, description: null, color: null, url: null,
    uploadedText: null, uploadedDays: null, sellerUsername: null, sellerRating: null, sellerFeedbackCount: null, sellerLastSeenText: null, sellerLastSeenDays: null,
    sellerBusiness: null, sellerBadges: [],
    found: [], missing: [],
  }

  const ldScripts = [...src.matchAll(/<script[^>]*type="application\/ld\+json"[^>]*>([\s\S]*?)<\/script>/gi)]
  for (const m of ldScripts) {
    try {
      const json = JSON.parse(m[1])
      const product = Array.isArray(json) ? json.find((j) => j && j['@type'] === 'Product') : (json && json['@type'] === 'Product' ? json : null)
      if (!product) continue
      out.title = product.name ? decodeEntities(product.name).trim() : null
      out.description = product.description ? decodeEntities(product.description).trim() : null
      out.brand = product.brand && (product.brand.name || product.brand) ? decodeEntities(product.brand.name || product.brand).trim() : null
      out.categoryText = product.category ? decodeEntities(product.category).trim() : null
      out.color = product.color ? decodeEntities(product.color).trim() : null
      const offer = Array.isArray(product.offers) ? product.offers[0] : product.offers
      if (offer) {
        const price = Number(String(offer.price).replace(',', '.'))
        out.listPrice = Number.isFinite(price) && price > 0 ? price : null
        out.currency = offer.priceCurrency || null
        const rawCondition = offer.itemCondition ? String(offer.itemCondition).replace(/^.*\//, '').replace(/Condition$/, '') : null
        out.condition = rawCondition ? (CONDITION_LABELS[rawCondition] || rawCondition) : null
        out.url = offer.url || null
      }
      break
    } catch {
      // malformed JSON-LD: fall back to meta tags below
    }
  }
  if (!out.title) {
    const og = firstMatch(src, /<meta property="og:title" content="([^"]*)"/i)
    if (og) out.title = decodeEntities(og).replace(/\s*\|\s*Vinted\s*$/i, '').trim()
  }
  if (!out.description) {
    const og = firstMatch(src, /<meta property="og:description" content="([^"]*)"/i)
    if (og) out.description = decodeEntities(og).trim()
  }

  const upload = firstMatch(src, /itemProp="upload_date"[^>]*>\s*<span[^>]*>([^<]+)</i) || firstMatch(src, /\\"value\\":\\"Caricato ([^"\\]+)\\"/)
  if (upload) {
    out.uploadedText = stripTags(upload).replace(/^caricato\s*/i, '')
    out.uploadedDays = parseRelativeItalian(out.uploadedText)
  }
  const lastSeen = firstMatch(src, /<[a-z0-9]+[^>]*data-testid="seller-last-logged-in"[^>]*>\s*([^<]+?)\s*<\//i)
  if (lastSeen) {
    out.sellerLastSeenText = stripTags(lastSeen)
    out.sellerLastSeenDays = parseRelativeItalian(out.sellerLastSeenText)
  }
  const username = firstMatch(src, /<[a-z0-9]+[^>]*data-testid="profile-username"[^>]*>\s*([^<]{1,80}?)\s*<\//i)
  if (username) out.sellerUsername = stripTags(username)
  const rating = firstMatch(src, /valutazione di ([\d.,]+) su 5 stelle/i)
  if (rating) out.sellerRating = Number(rating.replace(',', '.'))
  // The seller block is also embedded as escaped JSON (feedback_count, feedback_reputation 0..1, business flag, badges).
  const feedback = firstMatch(src, /\\"feedback_count\\":(\d+)/)
    || firstMatch(src, /web_ui__Rating__label[^>]*>(?:\s*<span[^>]*>)?\s*(\d+)\s*</i)
    || firstMatch(src, /su 5 stelle"[\s\S]{0,400}?>\s*\(?(\d+)\)?\s*<\/span>/i)
  if (feedback) out.sellerFeedbackCount = Number(feedback)
  else if (/Nessuna recensione|Nessuna valutazione/i.test(src)) out.sellerFeedbackCount = 0
  const reputation = firstMatch(src, /\\"feedback_reputation\\":([\d.]+)/)
  if (out.sellerRating === null && reputation) out.sellerRating = Math.round(Number(reputation) * 5 * 10) / 10
  const business = firstMatch(src, /\\"business\\":(true|false)[^}]{0,200}\\"feedback_count\\"/)
  if (business) out.sellerBusiness = business === 'true'
  const badgeBlock = firstMatch(src, /\\"badges\\":\[([^\]]*)\][^}]{0,80}\\"username\\"/)
  if (badgeBlock) out.sellerBadges = [...badgeBlock.matchAll(/\\"type\\":\\"([A-Z_]+)\\"/g)].map((m) => m[1])

  const labels = [
    ['title', 'titolo'], ['listPrice', 'prezzo'], ['brand', 'marca'], ['categoryText', 'categoria'], ['condition', 'condizioni'],
    ['uploadedText', 'data di caricamento'], ['sellerLastSeenText', 'attività del venditore'], ['sellerRating', 'valutazione del venditore'],
    ['sellerFeedbackCount', 'numero di recensioni'], ['description', 'descrizione'],
  ]
  for (const [key, label] of labels) (out[key] !== null && out[key] !== undefined ? out.found : out.missing).push(label)
  return out
}

/* ───────── mapping onto the analyzer ───────── */

const DECORATION = /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{2190}-\u{21FF}\u{2300}-\u{23FF}]|\u{FE0F}|\u{200D}/gu

/** Listing titles are quoted in the message to the seller: drop emoji and cut at a word boundary, never mid-word. */
function cleanTitle(title, max = 90) {
  const t = String(title || '').replace(DECORATION, ' ').replace(/\s+/g, ' ').trim()
  if (t.length <= max) return t
  const cut = t.slice(0, max)
  const at = cut.lastIndexOf(' ')
  return (at > max * 0.5 ? cut.slice(0, at) : cut).replace(/[\s,;:.\-–(]+$/, '')
}

const labelOf = (list, id) => ((list.find((x) => x.id === id) || {}).label || id)
const BADGE_LABELS = { ACTIVE_LISTER: 'pubblica spesso', SPEEDY_SHIPPING: 'spedisce in fretta', FAST_REPLIER: 'risponde in fretta' }

const LUXURY_BRANDS = /\b(gucci|prada|louis vuitton|chanel|herm[èe]s|dior|fendi|balenciaga|bottega veneta|burberry|versace|valentino|saint laurent|ysl|c[eé]line|loewe|givenchy|miu miu|rolex|cartier|omega|tiffany|bulgari|dolce\s*&\s*gabbana|armani(?! exchange)|moncler|golden goose|off-white|balmain|chlo[ée]|alexander mcqueen|jimmy choo|tod'?s|ferragamo|max mara)\b/i
const FAST_FASHION_BRANDS = /\b(zara|h\s*&\s*m|hm|shein|primark|bershka|pull\s*&\s*bear|stradivarius|mango|ovs|terranova|tezenis|calzedonia|intimissimi|kiabi|c\s*&\s*a|new yorker|uniqlo|asos|boohoo|prettylittlething|missguided|jennyfer|alcott|piazza italia|benetton|motivi|oviesse|subdued|brandy melville|hollister|abercrombie)\b/i
const SNEAKER_HINTS = /\b(sneakers?|scarpe da ginnastica|scarpe sportive|air force|air max|jordan|dunk|yeezy|new balance|nb\s?\d{3}|adidas samba|gazelle|campus|superstar|stan smith|converse|vans|asics|reebok|puma suede|hoka|salomon)\b/i
const ELECTRONICS_HINTS = /\b(elettronica|smartphone|iphone|samsung galaxy|pixel|tablet|ipad|console|playstation|ps[45]|xbox|nintendo|switch|cuffie|airpods|auricolari|smartwatch|apple watch|laptop|notebook|macbook|monitor|fotocamera|gopro|drone|kindle|dyson|speaker|videogioc)\b/i
const COLLECTIBLE_HINTS = /\b(collezionismo|collezione|carte|pok[ée]mon|yu-?gi-?oh|magic the gathering|funko|lego|vintage|fumett|manga|vinil|francobolli|monete|figure|statua|action figure|hot wheels|raro|rara|rare|limited|edizione limitata|prima edizione|autografat)\b/i
const KIDS_HINTS = /^(bambin[ie]|neonat[io]|ragazz[ie]|kids|bimb[aoie])\b|\b(bambin[ioae]|neonat[io]|ragazz[ioae]|bimb[aoie]|baby)\b/i

function categoryGuess({ categoryText = '', brand = '', title = '', description = '', listPrice = null }) {
  const cat = String(categoryText || '')
  const text = `${title || ''} ${description || ''}`
  const brandText = String(brand || '')
  if (KIDS_HINTS.test(cat)) return { id: 'kids', reason: `categoria "${cat}"` }
  if (LUXURY_BRANDS.test(brandText) || (LUXURY_BRANDS.test(title) && (listPrice === null || listPrice >= 80))) return { id: 'luxury', reason: `marca ${brandText || 'di lusso'}` }
  if (/\b(scarpe|sneakers|calzature)\b/i.test(cat) && (SNEAKER_HINTS.test(cat) || SNEAKER_HINTS.test(text) || /\b(nike|adidas|puma|new balance|reebok|asics|vans|converse|jordan)\b/i.test(brandText))) return { id: 'sneakers', reason: 'scarpe sportive' }
  if (SNEAKER_HINTS.test(title) && /\b(nike|adidas|puma|new balance|reebok|asics|vans|converse|jordan|hoka|salomon)\b/i.test(`${brandText} ${title}`)) return { id: 'sneakers', reason: 'titolo e marca' }
  if (ELECTRONICS_HINTS.test(cat) || (ELECTRONICS_HINTS.test(title) && /\b(apple|samsung|sony|nintendo|microsoft|xiaomi|huawei|google|dyson|bose|jbl|garmin)\b/i.test(`${brandText} ${title}`))) return { id: 'electronics', reason: 'elettronica' }
  if (COLLECTIBLE_HINTS.test(cat) || /\b(collezionismo|carte|fumetti|vinili|lego|funko|pok[ée]mon)\b/i.test(title)) return { id: 'collectible', reason: 'collezionismo' }
  if (FAST_FASHION_BRANDS.test(brandText)) return { id: 'fast_fashion', reason: `marca ${brandText}` }
  if (/^(donna|uomo|women|men)\b/i.test(cat) || /\b(abbigliamento|vestiti|maglie|felpe|pantaloni|jeans|giacche|abiti|gonne|camicie|t-shirt|scarpe)\b/i.test(cat)) {
    return { id: brandText ? 'other' : 'fast_fashion', reason: brandText ? `abbigliamento ${brandText}` : 'abbigliamento senza marca' }
  }
  return { id: 'other', reason: cat ? `categoria "${cat}"` : 'categoria non riconosciuta' }
}

function listingAgeGuess(days) {
  if (days === null || days === undefined || !Number.isFinite(days)) return 'unknown'
  if (days < 1) return 'today'
  if (days < 7) return 'days_2_6'
  if (days < 14) return 'weeks_1_2'
  if (days < 30) return 'weeks_2_4'
  return 'over_month'
}

function sellerProfileGuess({ lastSeenDays = null, feedbackCount = null, rating = null }) {
  if (lastSeenDays !== null && lastSeenDays >= 14) return { id: 'inactive', reason: `ultima visita ${Math.round(lastSeenDays)} giorni fa` }
  if (feedbackCount !== null && feedbackCount < 5) return { id: 'new_seller', reason: `${feedbackCount} recension${feedbackCount === 1 ? 'e' : 'i'}` }
  if (feedbackCount !== null && feedbackCount >= 20 && rating !== null && rating >= 4.8) return { id: 'expert', reason: `${feedbackCount} recensioni, ${rating} stelle` }
  if (feedbackCount === null && rating !== null && rating >= 4.8 && lastSeenDays !== null && lastSeenDays < 2) return { id: 'unknown', reason: 'valutazione alta ma recensioni non lette' }
  return { id: 'unknown', reason: 'dati insufficienti' }
}

const FIXED_PRICE = /\b(prezzo (fisso|non trattabile|non negoziabile|bloccato)|non trattabile|non negoziabile|no offerte|no offers|niente offerte|non accetto offerte|offerte? non accettat[ea]|no sconti|non faccio sconti|no trattative)\b/i
const OPEN_TO_OFFERS = /\b(accetto offerte|trattabile|trattabili|fate offerte|fatemi offerte|aperto a offerte|offerte benvenute|offerte ben accette|prezzo trattabile|si accettano offerte|accetto proposte|ascolto offerte)\b/i
const CLEARING_OUT = /\b(svuoto (l')?armadio|svuoto tutto|faccio spazio|vendo tutto|sgombero|devo liberare|cambio casa|trasloc[oa]|svendo|svendita|tutto deve andare|prezzi stracciati)\b/i

function signalFromText(text) {
  const t = String(text || '')
  if (FIXED_PRICE.test(t)) return { id: 'fixed_price', reason: 'l\'annuncio dice che il prezzo non è trattabile' }
  if (CLEARING_OUT.test(t)) return { id: 'clearing_out', reason: 'il venditore sta svuotando l\'armadio' }
  if (OPEN_TO_OFFERS.test(t)) return { id: 'open_to_offers', reason: 'l\'annuncio invita a fare offerte' }
  return { id: 'none', reason: 'nessun segnale nel testo' }
}

/** First plausible euro amount in free text ("8,90 €", "€ 25", "25€"). */
function findPriceInText(text) {
  const t = String(text || '')
  const m = t.match(/(\d{1,5}(?:[.,]\d{1,2})?)\s*€/) || t.match(/€\s*(\d{1,5}(?:[.,]\d{1,2})?)/)
  if (!m) return null
  const v = Number(m[1].replace(',', '.'))
  return Number.isFinite(v) && v > 0 ? v : null
}

const roundTarget = (value, listPrice) => (listPrice >= 20 ? Math.round(value) : Math.round(value * 2) / 2)
const euro = (n) => `${(Number.isInteger(n) ? String(n) : n.toFixed(2)).replace('.', ',')} €`

/**
 * Turns an extraction into form values plus a human summary. Fields the page did not provide
 * keep the previous form value (or the neutral default).
 */
function buildFormFromExtraction(ex, { link = '', targetDiscountPct = 20, previousForm = {} } = {}) {
  const found = []
  const guessed = []
  const missing = []
  const form = { ...previousForm, link: link || previousForm.link || ex.url || '' }

  const title = cleanTitle(ex.title)
  if (title) { form.itemTitle = title; found.push(`Titolo: ${title.length > 60 ? `${cleanTitle(title, 60)}…` : title}`) } else missing.push('titolo')
  if (ex.listPrice) {
    form.listPrice = String(ex.listPrice).replace('.', ',')
    const target = roundTarget(ex.listPrice * (1 - targetDiscountPct / 100), ex.listPrice)
    form.targetPrice = String(target).replace('.', ',')
    found.push(`Prezzo ${euro(ex.listPrice)} (target proposto ${euro(target)}, −${targetDiscountPct}%)`)
  } else missing.push('prezzo')

  const cat = categoryGuess(ex)
  form.category = cat.id
  guessed.push(`Categoria: ${labelOf(CATEGORIES, cat.id)} (${cat.reason})`)

  if (ex.uploadedDays !== null && ex.uploadedDays !== undefined) {
    form.listingAge = listingAgeGuess(ex.uploadedDays)
    found.push(`Caricato ${ex.uploadedText}`)
  } else { form.listingAge = previousForm.listingAge || 'unknown'; missing.push('data di caricamento') }

  const seller = sellerProfileGuess({ lastSeenDays: ex.sellerLastSeenDays, feedbackCount: ex.sellerFeedbackCount, rating: ex.sellerRating })
  form.sellerProfile = seller.id
  const sellerBits = [
    ex.sellerUsername ? ex.sellerUsername : null,
    ex.sellerLastSeenText ? ex.sellerLastSeenText.toLowerCase() : null,
    ex.sellerRating !== null ? `${ex.sellerRating} stelle` : null,
    ex.sellerFeedbackCount !== null ? `${ex.sellerFeedbackCount} recension${ex.sellerFeedbackCount === 1 ? 'e' : 'i'}` : null,
    ex.sellerBusiness ? 'venditore professionale' : null,
    ...(ex.sellerBadges || []).map((b) => BADGE_LABELS[b]).filter(Boolean),
  ].filter(Boolean)
  if (sellerBits.length) found.push(`Venditore: ${sellerBits.join(', ')}`)
  guessed.push(`Venditore: ${labelOf(SELLER_PROFILES, seller.id).toLowerCase()} (${seller.reason})`)
  if (ex.sellerFeedbackCount === null) missing.push('numero di recensioni')

  const signal = signalFromText(`${ex.title || ''} ${ex.description || ''}`)
  form.listingSignal = signal.id
  if (signal.id !== 'none') found.push(`Nell'annuncio: ${signal.reason}`)

  return { form, summary: { found, guessed, missing, condition: ex.condition, brand: ex.brand } }
}

